check("broadcast gateway rejects protected sale-ticket anchor spends", async () => {
  const signedTransactionInputOutpoints = isolatedFunction(
    API_PATH,
    "signedTransactionInputOutpoints",
    { bitcoin, Buffer },
  );
  let queriedOutpoints = [];
  let indexedAnchors = [];
  let signedCloseListingIds = new Set();
  const protectedListingAnchorSpendError = ({
    anchors,
    code,
    message,
    reasonCode,
  }) => {
    const error = new Error(message);
    error.statusCode = 400;
    error.details = { anchors, code, reasonCode };
    return error;
  };
  const assertNoUnexpectedListingAnchorSpend = isolatedFunction(
    API_PATH,
    "assertNoUnexpectedListingAnchorSpend",
    {
      proofIndexActiveCreditListingAnchorMatches: async (network, outpoints) => {
        assert.equal(network, "livenet");
        queriedOutpoints = outpoints;
        return indexedAnchors;
      },
      protectedListingAnchorSpendError,
      signedTransactionInputOutpoints,
      signedTokenListingCloseIds: () => signedCloseListingIds,
    },
  );
  const tx = new bitcoin.Transaction();
  tx.addInput(Buffer.from("11".repeat(32), "hex").reverse(), 2);
  tx.addInput(Buffer.from("22".repeat(32), "hex").reverse(), 3);
  tx.addOutput(
    bitcoin.script.compile([
      bitcoin.opcodes.OP_RETURN,
      Buffer.from("not-a-market-action", "utf8"),
    ]),
    0n,
  );
  indexedAnchors = signedTransactionInputOutpoints(tx.toHex()).map(
    (outpoint, index) => ({
      anchorTxid: outpoint.txid,
      anchorVout: outpoint.vout,
      listingId: `${String(index + 1).repeat(64)}`.slice(0, 64),
      sellerAddress: `seller-${index + 1}`,
      tokenId: WORK_TOKEN_ID,
    }),
  );

  await assert.rejects(
    () => assertNoUnexpectedListingAnchorSpend(tx.toHex(), "livenet"),
    (error) => {
      assert.equal(error.statusCode, 400);
      assert.equal(
        error.details?.code,
        "PROTECTED_LISTING_ANCHOR_MULTI_SPEND",
      );
      assert.equal(error.details?.anchors?.length, 2);
      return true;
    },
  );
  assert.deepEqual(
    queriedOutpoints.map((outpoint) => outpoint.vout),
    [2, 3],
  );

  const singleAnchorTx = new bitcoin.Transaction();
  singleAnchorTx.addInput(Buffer.from("33".repeat(32), "hex").reverse(), 4);
  singleAnchorTx.addOutput(
    bitcoin.script.compile([
      bitcoin.opcodes.OP_RETURN,
      Buffer.from("generic-wallet-send", "utf8"),
    ]),
    0n,
  );
  indexedAnchors = signedTransactionInputOutpoints(singleAnchorTx.toHex()).map(
    (outpoint) => ({
      anchorTxid: outpoint.txid,
      anchorVout: outpoint.vout,
      listingId: "3".repeat(64),
      sellerAddress: "seller-3",
      tokenId: WORK_TOKEN_ID,
    }),
  );
  signedCloseListingIds = new Set();
  await assert.rejects(
    () =>
      assertNoUnexpectedListingAnchorSpend(singleAnchorTx.toHex(), "livenet"),
    (error) => {
      assert.equal(error.statusCode, 400);
      assert.equal(
        error.details?.code,
        "PROTECTED_LISTING_ANCHOR_UNEXPECTED_SPEND",
      );
      assert.equal(error.details?.anchors?.length, 1);
      return true;
    },
  );

  signedCloseListingIds = new Set(["3".repeat(64)]);
  await assertNoUnexpectedListingAnchorSpend(singleAnchorTx.toHex(), "livenet");
});

check("WORK broadcast admission resolves confirmed input addresses", async () => {
  const expectedAddress = "1BoatSLRHtKNngkdXEeobR76b53LETtpyT";
  const previousTxid = "ab".repeat(32);
  const addressFromVout = isolatedFunction(API_PATH, "addressFromVout");
  const signedTransactionInputAddresses = isolatedFunction(
    API_PATH,
    "signedTransactionInputAddresses",
    {
      TX_FETCH_CONCURRENCY: 4,
      addressFromVout,
      fetchTransactionFromBitcoinRpc: async (txid, network, options) => {
        assert.equal(txid, previousTxid);
        assert.equal(network, "livenet");
        assert.deepEqual(JSON.parse(JSON.stringify(options)), {
          bypassCache: true,
          includePrevouts: false,
          requireCanonicalPrevouts: true,
        });
        return {
          status: { confirmed: true },
          vout: [{ scriptpubkey_address: expectedAddress }],
        };
      },
      mapWithConcurrency: async (items, _concurrency, mapper) =>
        Promise.all(items.map(mapper)),
      transactionConfirmed: (tx) => tx?.status?.confirmed === true,
    },
  );

  assert.deepEqual(
    JSON.parse(
      JSON.stringify(
        await signedTransactionInputAddresses(
          [{ txid: previousTxid, vout: 0 }],
          "livenet",
        ),
      ),
    ),
    [expectedAddress],
  );
});

check("WORK broadcast admission matches raw single-output and first-actor rules", async () => {
  const registryAddress = "1638Vn6KtmK8p5r4oGvAXq9nmZb1emU1DV";
  const buyerAddress = "1F1p9UEHuH5KTFR7Zsx93Khdrqhj6t5nFv";
  const otherAddress = "1BoatSLRHtKNngkdXEeobR76b53LETtpyT";
  const sellerAddress = bitcoin.payments.p2wpkh({
    network: bitcoin.networks.bitcoin,
    pubkey: Buffer.from(`02${"11".repeat(32)}`, "hex"),
  }).address;
  assert.ok(sellerAddress);
  const listingId = "a".repeat(64);
  const authorization = {
    anchorTxid: listingId,
    anchorSignature: "30".repeat(36),
    anchorSigHashType: 0x83,
    anchorType: "sale-ticket-v1",
    anchorValueSats: 546,
    anchorVout: 2,
    priceSats: 0,
    sellerAddress,
    tokenId: WORK_TOKEN_ID,
    version: WORK_AMO_V5_AUTH_VERSION,
  };
  const buyMessage = `pwt1:buy5:${listingId}:${buyerAddress}:fixture`;
  const sealMessage = `pwt1:seal5:${listingId}:fixture`;
  const scriptFor = (address) =>
    Buffer.from(
      bitcoin.address.toOutputScript(
        address,
        bitcoin.networks.bitcoin,
      ),
    ).toString("hex");
  const protocolOutput = (message) => {
    const protocolPayload = Buffer.from(message, "utf8");
    return {
      scriptpubkey: Buffer.concat([
        Buffer.from(
          protocolPayload.length <= 0x4b
            ? [0x6a, protocolPayload.length]
            : [0x6a, 0x4c, protocolPayload.length],
        ),
        protocolPayload,
      ]).toString("hex"),
      value: 0,
    };
  };
  let outputFixture = [];
  let originFixture = [buyerAddress];
  let inputOutpointsFixture = [{ txid: listingId, vout: 2 }];
  let buyerLockFixture = "";
  let saleTicketSignatureValidFixture = true;
  const signedWorkAmoEconomicOutputs = isolatedFunction(
    API_PATH,
    "signedWorkAmoEconomicOutputs",
    {
      Buffer,
      bitcoin,
      bitcoinNetwork: () => bitcoin.networks.bitcoin,
    },
  );
  const signedSinglePaymentAmountBeforeTokenProtocol = isolatedFunction(
    API_PATH,
    "signedSinglePaymentAmountBeforeTokenProtocol",
    { assignWorkAmoV5EconomicOutputs },
  );
  const signedWorkMarketplaceWriteActions = isolatedFunction(
    API_PATH,
    "signedWorkMarketplaceWriteActions",
    {
      TOKEN_BUY_ACTION: "buy5",
      TOKEN_DELIST_ACTION: "delist5",
      TOKEN_LIST_ACTION: "list5",
      TOKEN_LISTING_ANCHOR_VOUT: 2,
      TOKEN_MIN_MUTATION_PRICE_SATS: 546,
      TOKEN_PROTOCOL_PREFIX: "pwt1:",
      TOKEN_SALE_AUTH_WORK_AMO_V5_VERSION: WORK_AMO_V5_AUTH_VERSION,
      TOKEN_SALE_AUTH_WORK_AMO_V6_VERSION: WORK_AMO_V6_AUTH_VERSION,
      TOKEN_SALE_AUTH_WORK_AMO_V8_VERSION: WORK_AMO_V8_AUTH_VERSION,
      TOKEN_SALE_AUTH_WORK_MARKET_V4_VERSION: WORK_AMO_V4_AUTH_VERSION,
      TOKEN_SEAL_ACTION: "seal5",
      TX_FETCH_CONCURRENCY: 4,
      WORK_AMO_V5_DECLARATION_REGISTRY_ADDRESS: registryAddress,
      WORK_TOKEN_DEFAULT_REGISTRY_ADDRESS: registryAddress,
      canonicalProtocolCandidateFromOutput,
      canonicalWorkMarketplaceListingAnchor: async () => ({
        anchorVout: 2,
        frozenTerms: { unitPriceSats: "2000" },
        listingId,
        saleAuthorization: authorization,
      }),
      decodedProtocolMessages: (outputs) =>
        outputs.some((output) => output.protocol === true)
          ? [buyMessage]
          : [],
      mapWithConcurrency: async (items, _limit, mapper) =>
        Promise.all(items.map(mapper)),
      parseTokenPayload: () => ({
        buyerAddress,
        saleAuthorization: {
          ...authorization,
          ...(buyerLockFixture
            ? { buyerAddress: buyerLockFixture }
            : {}),
        },
      }),
      rawTokenSaleAuthorization: () => authorization,
      selectWorkAmoV5DistinctRegistryPayment,
      signedSinglePaymentAmountBeforeTokenProtocol,
      signedTransactionInputAddresses: async () => originFixture,
      signedTransactionInputOutpoints: () => inputOutpointsFixture,
      signedTransactionOutputs: () => outputFixture,
      signedWorkAmoEconomicOutputs,
      tokenListingAnchorIsPresent: () => true,
      tokenSaleAuthorizationTermsMatch: () => true,
      tokenSaleAuthorizationUsesSaleTicketAnchor: () => true,
      validateWorkAmoV5SaleTicketSignature: () => ({
        valid: saleTicketSignatureValidFixture,
      }),
      workMarketplaceWriteActionIsGoverned: (_action, context) =>
        context.paysWorkRegistry === true,
    },
  );
  const registry = (value) => ({
    scriptpubkey: scriptFor(registryAddress),
    value,
  });
  const seller = (value) => ({
    scriptpubkey: scriptFor(sellerAddress),
    value,
  });
  const actions = async (
    outputs,
    origins = [buyerAddress],
    inputOutpoints = [{ txid: listingId, vout: 2 }],
  ) => {
    outputFixture = outputs;
    originFixture = origins;
    inputOutpointsFixture = inputOutpoints;
    return signedWorkMarketplaceWriteActions("fixture", "livenet");
  };

  let result = await actions([
    registry(546),
    seller(2_546),
    protocolOutput(buyMessage),
  ]);
  assert.equal(result[0]?.paysWorkRegistry, true);
  assert.equal(result[0]?.signedShapeValid, true);

  result = await actions(
    [registry(546), seller(2_546), protocolOutput(buyMessage)],
    ["", buyerAddress],
  );
  assert.equal(result[0]?.signedShapeValid, true);

  result = await actions([
    registry(300),
    registry(246),
    seller(2_546),
    protocolOutput(buyMessage),
  ]);
  assert.equal(result[0]?.paysWorkRegistry, false);

  result = await actions([
    registry(546),
    seller(1_200),
    seller(1_346),
    protocolOutput(buyMessage),
  ]);
  assert.equal(result[0]?.signedShapeValid, false);

  result = await actions(
    [registry(546), seller(2_546), protocolOutput(buyMessage)],
    [otherAddress],
  );
  assert.equal(result[0]?.signedShapeValid, false);

  buyerLockFixture = otherAddress;
  result = await actions([
    registry(546),
    seller(2_546),
    protocolOutput(buyMessage),
  ]);
  assert.equal(result[0]?.signedShapeValid, false);
  buyerLockFixture = "";

  result = await actions(
    [registry(546), protocolOutput(sealMessage)],
    [otherAddress],
    [],
  );
  assert.equal(
    result[0]?.signedShapeValid,
    true,
    "seal actor proof comes from the sale-ticket signature, not the fee input",
  );

  saleTicketSignatureValidFixture = false;
  result = await actions(
    [registry(546), protocolOutput(sealMessage)],
    [otherAddress],
    [],
  );
  assert.equal(result[0]?.signedShapeValid, false);
  saleTicketSignatureValidFixture = true;

  const malformedProtocolOutput = {
    ...protocolOutput(buyMessage),
    scriptpubkey: `${protocolOutput(buyMessage).scriptpubkey}0561`,
  };
  await assert.rejects(
    () =>
      actions([
        registry(546),
        seller(2_546),
        malformedProtocolOutput,
      ]),
    (error) =>
      error?.statusCode === 400 &&
      error?.details?.reasonCode ===
        CANONICAL_OP_RETURN_SCRIPT_MALFORMED,
  );
});

