check("WORK V3 seal confirmation requires its canonical valid event", () => {
  const sealTxid = "4".repeat(64);
  const workTokenId = "d4e5ebf11d104d6a63fb74e42094364b25a5f7199a09e5c0e71408972466a8b8";
  const tokenListingSealConfirmedFromTransaction = isolatedFunction(
    READER_PATH,
    "tokenListingSealConfirmedFromTransaction",
    {
      normalizedLowerText: (value) => String(value ?? "").trim().toLowerCase(),
      validTxid: (value) => /^[0-9a-f]{64}$/u.test(String(value ?? "")),
      WORK_MARKET_GOVERNED_AUTH_VERSIONS:
        WORK_MARKET_GOVERNED_AUTH_VERSIONS_FIXTURE,
      WORK_MARKET_V2_AUTH_VERSION: "pwt-sale-v3",
      WORK_TOKEN_ID: workTokenId,
    },
  );

  assert.equal(
    tokenListingSealConfirmedFromTransaction(
      { seal_tx_status: "pending" },
      sealTxid,
    ),
    false,
  );
  assert.equal(
    tokenListingSealConfirmedFromTransaction(
      { seal_tx_status: "confirmed" },
      sealTxid,
    ),
    false,
    "a confirmed seal with unknown relational and transaction height fails closed",
  );
  assert.equal(
    tokenListingSealConfirmedFromTransaction(
      {
        seal_transaction_block_height:
          WORK_AMO_V5_ACTIVATION_HEIGHT - 1,
        seal_tx_status: "confirmed",
      },
      sealTxid,
    ),
    true,
    "a positively known pre-V5 generic seal keeps legacy compatibility",
  );
  const workMarketV3Row = {
    payload: {
      saleAuthorization: {
        tokenId: workTokenId,
        version: "pwt-sale-v3",
      },
    },
    seal_transaction_block_height:
      WORK_AMO_V5_ACTIVATION_HEIGHT - 1,
    seal_tx_status: "confirmed",
    token_id: workTokenId,
  };
  assert.equal(
    tokenListingSealConfirmedFromTransaction(workMarketV3Row, sealTxid),
    false,
  );
  assert.equal(
    tokenListingSealConfirmedFromTransaction(
      {
        ...workMarketV3Row,
        seal_event_match_count: 1,
        seal_event_status: "confirmed",
      },
      sealTxid,
    ),
    true,
  );
  assert.equal(
    tokenListingSealConfirmedFromTransaction(
      { ...workMarketV3Row, seal_event_status: "confirmed" },
      sealTxid,
    ),
    false,
    "required canonical seal evidence must include an exact singleton count",
  );
  assert.equal(
    tokenListingSealConfirmedFromTransaction({}, sealTxid),
    false,
  );
  assert.equal(
    tokenListingSealConfirmedFromTransaction(
      { seal_tx_status: "confirmed" },
      "not-a-txid",
    ),
    false,
  );

  const readerSource = fileSource(READER_PATH);
  assert.equal(
    (readerSource.match(/seal_tx\.status AS seal_tx_status/gu) ?? []).length,
    5,
  );
  assert.equal(
    (readerSource.match(/canonical_seal_event\.seal_event_status/gu) ?? [])
      .length >= 4,
    true,
  );
  assert.equal(
    (readerSource.match(
      /(?<!function )tokenListingSealConfirmedFromTransaction\(\s*row,\s*sealTxid,?\s*\)/gu,
    ) ?? []).length,
    4,
  );
});

check("WORK V3 projections accept only confirmed action components", async () => {
  const workTokenId =
    "d4e5ebf11d104d6a63fb74e42094364b25a5f7199a09e5c0e71408972466a8b8";
  const normalizedLowerText = (value) =>
    String(value ?? "").trim().toLowerCase();
  const objectValue = (value) =>
    value && typeof value === "object" && !Array.isArray(value) ? value : {};
  const identity = isolatedFunction(
    BACKFILL_PATH,
    "workMarketV2ProjectionIdentity",
    {
      normalizedLowerText,
      objectValue,
    },
  );
  const canMutate = isolatedFunction(
    BACKFILL_PATH,
    "workMarketV2ProjectionCanMutate",
    {
      eventKind: (item) => item.kind,
      isHexTxid: (value) => /^[0-9a-f]{64}$/u.test(String(value ?? "")),
      NETWORK: "livenet",
      normalizedLowerText,
      workMarketV2ProjectionIdentity: identity,
      WORK_MARKET_GOVERNED_AUTH_VERSIONS:
        WORK_MARKET_GOVERNED_AUTH_VERSIONS_FIXTURE,
      WORK_MARKET_V2_AUTH_VERSION: "pwt-sale-v3",
      WORK_TOKEN_ID: workTokenId,
    },
  );
  const base = {
    confirmed: true,
    listingId: "1".repeat(64),
    saleAuthorization: {
      tokenId: workTokenId,
      version: "pwt-sale-v3",
    },
    tokenId: workTokenId,
  };
  const noParentRead = {
    async query() {
      throw new Error("explicit V3 projection unexpectedly queried its parent");
    },
  };

  assert.equal(
    await canMutate(
      noParentRead,
      base,
      "pending",
      "token-listing",
      "token-listings",
    ),
    false,
  );
  assert.equal(
    await canMutate(
      noParentRead,
      base,
      "confirmed",
      "token-listing",
      "token-listings",
    ),
    true,
  );
  assert.equal(
    await canMutate(
      noParentRead,
      { ...base, sealConfirmed: false, sealTxid: "2".repeat(64) },
      "confirmed",
      "token-listing-sealed",
      "token-listings",
    ),
    false,
  );
  assert.equal(
    await canMutate(
      noParentRead,
      { ...base, sealConfirmed: true, sealTxid: "2".repeat(64) },
      "confirmed",
      "token-listing-sealed",
      "token-listings",
    ),
    true,
  );
  assert.equal(
    await canMutate(
      noParentRead,
      { ...base, closedConfirmed: false },
      "confirmed",
      "token-sale",
      "token-sales",
    ),
    false,
  );
  assert.equal(
    await canMutate(
      noParentRead,
      { ...base, closedConfirmed: true },
      "confirmed",
      "token-sale",
      "token-sales",
    ),
    true,
  );
  assert.equal(
    await canMutate(
      noParentRead,
      {
        ...base,
        saleAuthorization: { tokenId: "3".repeat(64), version: "pwt-sale-v3" },
        tokenId: "3".repeat(64),
      },
      "pending",
      "token-listing",
      "token-listings",
    ),
    true,
  );
  const companion = {
    closedConfirmed: false,
    confirmed: false,
    listingId: base.listingId,
    tokenId: workTokenId,
  };
  const parentReads = [];
  const v3ParentClient = {
    async query(sql, params) {
      parentReads.push({ params: [...params], sql: String(sql) });
      return { rows: [{ authorization_version: "pwt-sale-v3" }] };
    },
  };
  assert.equal(
    await canMutate(
      v3ParentClient,
      companion,
      "pending",
      "token-listing-closed",
      "token-closed-listings",
    ),
    false,
  );
  assert.equal(parentReads.length, 1);
  assert.deepEqual(parentReads[0].params, [
    "livenet",
    base.listingId,
    workTokenId,
  ]);
  assert.match(parentReads[0].sql, /FROM proof_indexer\.credit_listings/u);

  const projectionWrites = [];
  const upsertProjection = isolatedFunction(
    BACKFILL_PATH,
    "upsertProjection",
    {
      bondTagForKind: () => null,
      eventKind: (item) => item.kind ?? "token-listing-closed",
      workMarketV2ProjectionCanMutate: canMutate,
    },
  );
  await upsertProjection(
    {
      async query(sql, params) {
        const text = String(sql);
        if (/SELECT lower\(COALESCE/iu.test(text)) {
          return { rows: [{ authorization_version: "pwt-sale-v3" }] };
        }
        projectionWrites.push({ params, sql: text });
        return { rows: [] };
      },
    },
    "token-closed-listings",
    companion,
    "pending",
  );
  assert.equal(projectionWrites.length, 0);
});

check("WORK V3 aggregate rows cannot rewrite action-bound events", async () => {
  const workTokenId =
    "d4e5ebf11d104d6a63fb74e42094364b25a5f7199a09e5c0e71408972466a8b8";
  const normalizedLowerText = (value) =>
    String(value ?? "").trim().toLowerCase();
  const objectValue = (value) =>
    value && typeof value === "object" && !Array.isArray(value) ? value : {};
  const isHexTxid = (value) => /^[0-9a-f]{64}$/u.test(String(value ?? ""));
  const identity = isolatedFunction(
    BACKFILL_PATH,
    "workMarketV2ProjectionIdentity",
    { normalizedLowerText, objectValue },
  );
  const actionBound = isolatedFunction(
    BACKFILL_PATH,
    "workMarketV2EventIsActionBound",
    {
      isHexTxid,
      normalizedLowerText,
      workMarketV2ProjectionIdentity: identity,
      WORK_MARKET_GOVERNED_AUTH_VERSIONS:
        WORK_MARKET_GOVERNED_AUTH_VERSIONS_FIXTURE,
      WORK_MARKET_V2_AUTH_VERSION: "pwt-sale-v3",
      WORK_TOKEN_ID: workTokenId,
    },
  );
  const listingId = "4".repeat(64);
  const sealTxid = "5".repeat(64);
  const authorization = { tokenId: workTokenId, version: "pwt-sale-v3" };
  const aggregate = {
    listingId,
    saleAuthorization: authorization,
    sealConfirmed: false,
    sealTxid,
    tokenId: workTokenId,
    txid: listingId,
  };
  assert.equal(actionBound(aggregate, "token-listing", listingId), false);
  assert.equal(
    actionBound(
      { ...aggregate, sealTxid: undefined },
      "token-listing",
      listingId,
    ),
    true,
  );
  assert.equal(
    actionBound(
      { ...aggregate, sealTxid: undefined, txid: sealTxid },
      "token-listing",
      sealTxid,
    ),
    false,
  );
  assert.equal(
    actionBound(
      { ...aggregate, kind: "token-listing-sealed", txid: sealTxid },
      "token-listing-sealed",
      sealTxid,
    ),
    true,
  );
  assert.equal(
    actionBound(
      { ...aggregate, kind: "token-listing-sealed", txid: "6".repeat(64) },
      "token-listing-sealed",
      "6".repeat(64),
    ),
    false,
  );
  const saleTxid = "a".repeat(64);
  assert.equal(
    actionBound(
      { ...aggregate, kind: "token-sale", saleTxid, txid: saleTxid },
      "token-sale",
      saleTxid,
    ),
    true,
  );
  assert.equal(
    actionBound(
      { ...aggregate, kind: "token-sale", saleTxid, txid: "b".repeat(64) },
      "token-sale",
      "b".repeat(64),
    ),
    false,
  );
  assert.equal(
    actionBound(
      { ...aggregate, kind: "buy", saleTxid, txid: saleTxid },
      "buy",
      saleTxid,
    ),
    true,
  );
  assert.equal(
    actionBound(
      { ...aggregate, kind: "buy", saleTxid, txid: "b".repeat(64) },
      "buy",
      "b".repeat(64),
    ),
    false,
  );
  assert.equal(
    actionBound(
      { ...aggregate, kind: undefined, saleTxid, txid: saleTxid },
      "token-sales",
      saleTxid,
    ),
    true,
  );
  assert.equal(
    actionBound(
      { ...aggregate, kind: undefined, saleTxid, txid: "b".repeat(64) },
      "token-sales",
      "b".repeat(64),
    ),
    false,
  );
  const closeTxid = "c".repeat(64);
  assert.equal(
    actionBound(
      {
        ...aggregate,
        closedTxid: closeTxid,
        kind: "token-listing-closed",
        txid: closeTxid,
      },
      "token-listing-closed",
      closeTxid,
    ),
    true,
  );
  assert.equal(
    actionBound(
      {
        ...aggregate,
        closedTxid: closeTxid,
        kind: "token-listing-closed",
        txid: "d".repeat(64),
      },
      "token-listing-closed",
      "d".repeat(64),
    ),
    false,
  );
  assert.equal(
    actionBound(
      {
        ...aggregate,
        closedTxid: closeTxid,
        kind: undefined,
        txid: closeTxid,
      },
      "token-closed-listings",
      closeTxid,
    ),
    true,
  );
  assert.equal(
    actionBound(
      {
        ...aggregate,
        closedTxid: closeTxid,
        kind: undefined,
        txid: "d".repeat(64),
      },
      "token-closed-listings",
      "d".repeat(64),
    ),
    false,
  );

  let databaseCalls = 0;
  const upsertEvent = isolatedFunction(BACKFILL_PATH, "upsertEvent", {
    eventKind: () => "token-listing",
    itemStatus: () => "confirmed",
    itemTxid: (item) => item.txid,
    workMarketV2EventIsActionBound: actionBound,
  });
  const result = await upsertEvent(
    {
      async query() {
        databaseCalls += 1;
        throw new Error("aggregate row reached persistence");
      },
    },
    "token-listings",
    aggregate,
  );
  assert.equal(result.aggregateSkipped, true);
  assert.equal(result.skipped, true);
  assert.equal(databaseCalls, 0);
});

check("canonical WORK V3 decisions remove volatile marketplace events", async () => {
  const queries = [];
  const removeVolatile = isolatedFunction(
    BACKFILL_PATH,
    "removeVolatileWorkMarketV2DecisionEvents",
    {
      normalizedLowerText: (value) => String(value ?? "").trim().toLowerCase(),
      NETWORK: "livenet",
      WORK_MARKET_V4_AUTH_VERSION: "pwt-sale-v4",
      WORK_MARKET_V2_AUTH_VERSION: "pwt-sale-v3",
      WORK_TOKEN_ID:
        "d4e5ebf11d104d6a63fb74e42094364b25a5f7199a09e5c0e71408972466a8b8",
    },
  );
  const txid = "7".repeat(64);
  const tokenVerifierItemsFromState = isolatedFunction(
    API_PATH,
    "tokenVerifierItemsFromState",
  );
  const [canonicalInvalid] = tokenVerifierItemsFromState(
    {
      canonicalCoverage: true,
      invalidEvents: [{
        blockHeight: 958_000,
        blockIndex: 1,
        confirmed: true,
        kind: "seal",
        protocolVout: 0,
        tokenId:
          "d4e5ebf11d104d6a63fb74e42094364b25a5f7199a09e5c0e71408972466a8b8",
        txid,
      }],
    },
    txid,
  );
  assert.equal(canonicalInvalid.kind, "token-event-invalid");
  assert.equal(canonicalInvalid.attemptedKind, "seal");
  const client = {
    async query(sql, params) {
      queries.push({ params, sql: String(sql) });
      return { rowCount: 1, rows: [] };
    },
  };
  assert.equal(
    await removeVolatile(
      client,
      [canonicalInvalid],
      txid,
    ),
    1,
  );
  assert.equal(queries.length, 1);
  assert.deepEqual(
    JSON.parse(JSON.stringify([...queries[0].params])),
    [
      "livenet",
      txid,
      "d4e5ebf11d104d6a63fb74e42094364b25a5f7199a09e5c0e71408972466a8b8",
      ["pwt-sale-v3", "pwt-sale-v4", "pwt-sale-v5"],
    ],
  );
  assert.match(queries[0].sql, /status IN \('pending', 'dropped', 'orphaned'\)/u);
  assert.match(queries[0].sql, /saleAuthorization'->>'version'/u);
  assert.match(
    queries[0].sql,
    /FROM proof_indexer\.credit_listings parent_listing/u,
  );
});

check("full token mint reads deduplicate without sorting wide payloads", async () => {
  const canonicalTokenMintCandidateRows = isolatedFunction(
    READER_PATH,
    "canonicalTokenMintCandidateRows",
  );
  const common = {
    mint_ordinal: 0,
    mint_recipient_address: "bc1Minter",
    token_id: "A".repeat(64),
    txid: "B".repeat(64),
  };
  const rows = [
    {
      ...common,
      block_height: null,
      effective_status: "pending",
      event_id: "1",
      mint_winner_time_us: "200",
    },
    {
      ...common,
      block_height: 100,
      effective_status: "confirmed",
      event_id: "2",
      mint_winner_time_us: "100",
    },
    {
      ...common,
      block_height: null,
      effective_status: "confirmed",
      event_id: "3",
      mint_winner_time_us: "300",
    },
    {
      ...common,
      block_height: 100,
      effective_status: "confirmed",
      event_id: "4",
      mint_winner_time_us: "200",
    },
    {
      ...common,
      block_height: 100,
      effective_status: "confirmed",
      event_id: "5",
      mint_winner_time_us: "200",
    },
    {
      ...common,
      event_id: "6",
      mint_recipient_address: "bc1Other",
      mint_winner_time_us: "50",
    },
  ];
  assert.equal(
    JSON.stringify(
      canonicalTokenMintCandidateRows(rows)
        .map((row) => String(row.event_id))
        .sort(),
    ),
    JSON.stringify(["5", "6"]),
  );
  const orderedRows = [
    ["10", "300", 100, "d", 0, "bc1a", "1"],
    ["20", "200", 101, "d", 0, "bc1a", "2"],
    ["30", "200", 100, "f", 9, "bc1z", "3"],
    ["40", "200", 100, "e", 0, "bc1a", "4"],
    ["41", "200", 100, "e", 0, "bc1a", "5"],
    ["42", "200", 100, "e", 0, "bc1b", "4"],
    ["43", "200", 100, "e", 1, "bc1a", "4"],
    ["50", "200", null, "f", 0, "bc1a", "4"],
  ].map(([eventId, time, height, txidDigit, mintOrdinal, recipient, tokenDigit]) => ({
    block_height: height,
    effective_status: "confirmed",
    event_id: eventId,
    mint_ordinal: mintOrdinal,
    mint_recipient_address: recipient,
    mint_winner_time_us: time,
    token_id: tokenDigit.repeat(64),
    txid: txidDigit.repeat(64),
  }));
  assert.equal(
    JSON.stringify(
      canonicalTokenMintCandidateRows([...orderedRows].reverse()).map((row) =>
        String(row.event_id),
      ),
    ),
    JSON.stringify(["10", "20", "30", "41", "40", "42", "43", "50"]),
  );
  const v5Common = {
    block_height: WORK_AMO_V5_ACTIVATION_HEIGHT,
    block_index: 7,
    effective_status: "confirmed",
    mint_ordinal: null,
    mint_recipient_address: "bc1same",
    mint_winner_time_us: "500",
    token_id: "7".repeat(64),
    txid: "8".repeat(64),
  };
  const v5Rows = [
    {
      ...v5Common,
      event_id: "60",
      op_return_vout: 2,
      record_ordinal: 0,
    },
    {
      ...v5Common,
      event_id: "61",
      op_return_vout: 3,
      record_ordinal: 1,
    },
  ];
  assert.equal(
    JSON.stringify(
      canonicalTokenMintCandidateRows([...v5Rows].reverse())
        .map((row) => [row.op_return_vout, row.record_ordinal]),
    ),
    JSON.stringify([[2, 0], [3, 1]]),
  );
  assert.throws(
    () =>
      canonicalTokenMintCandidateRows([
        { ...v5Rows[0], record_ordinal: null },
      ]),
    /mint candidate position is incomplete/u,
  );

  const queries = [];
  const proofIndexTokenMintRows = isolatedFunction(
    READER_PATH,
    "proofIndexTokenMintRows",
    {
      canonicalTokenMintCandidateRows,
      tokenMintEventQueryParts: () => ({
        candidateCte: "WITH mint_candidates AS (SELECT 1)",
        params: ["livenet"],
      }),
    },
  );
  await proofIndexTokenMintRows(
    {
      async query(sql, params) {
        queries.push({ params, sql: String(sql) });
        return { rows };
      },
    },
    "livenet",
    common.token_id,
    new URLSearchParams(),
    { limit: 100_000, offset: 0 },
  );
  assert.equal(queries.length, 1);
  assert.match(queries[0].sql, /FROM mint_candidates/u);
  assert.match(queries[0].sql, /mint_winner_time_us/u);
  assert.doesNotMatch(queries[0].sql, /ORDER BY/u);
  assert.doesNotMatch(queries[0].sql, /FROM mint_events/u);
});

