check("fresh WORK token reads prefer canonical summary over lagging token-state", async () => {
  const workTokenId = "work-token-id";
  const blockHash = "8".repeat(64);
  const canonicalGate = {
    atTip: false,
    canonicalHash: blockHash,
    indexedThroughBlock: 200,
    lagBlocks: 1,
    ok: true,
    tipHeight: 201,
  };
  const canonicalSummary = {
    indexedThroughBlock: 200,
    indexedThroughBlockHash: blockHash,
    listings: [{ listingId: "listing", version: "pwt-sale-v8" }],
    snapshotId: "summary-200",
    summaryOnly: true,
    tokens: [{ openListings: 1, tokenId: workTokenId }],
  };
  let summaryReads = 0;
  const canonicalSummaryFreshRead = isolatedFunction(
    API_PATH,
    "currentCanonicalWorkTokenSummaryPayloadForFreshRead",
    {
      WORK_TOKEN_ID: workTokenId,
      normalizeTokenScope: (value) =>
        String(value ?? "").trim().toUpperCase() === "WORK"
          ? workTokenId
          : String(value ?? "").trim().toLowerCase(),
      rejectEmptyMainnetTokenPayload: () => false,
      storedCanonicalTokenSummaryPayload: async () => {
        summaryReads += 1;
        return canonicalSummary;
      },
      tokenPayloadMatchesCanonicalIndexedGate: (payload, gate) =>
        gate?.ok === true &&
        Number(payload?.indexedThroughBlock) === gate.indexedThroughBlock &&
        payload?.indexedThroughBlockHash === gate.canonicalHash,
    },
  );

  assert.equal(
    await canonicalSummaryFreshRead("livenet", "WORK", canonicalGate),
    canonicalSummary,
  );
  assert.equal(summaryReads, 1);
  assert.equal(
    await canonicalSummaryFreshRead("livenet", "other-token-id", canonicalGate),
    null,
  );
  assert.equal(summaryReads, 1);
  assert.equal(
    await canonicalSummaryFreshRead(
      "livenet",
      "WORK",
      { ...canonicalGate, canonicalHash: "9".repeat(64) },
    ),
    null,
  );

  const requestSource = topLevelFunctionSource(API_PATH, "handleRequest");
  const summaryReadIndex = requestSource.indexOf(
    "currentCanonicalWorkTokenSummaryPayloadForFreshRead",
  );
  const tokenStateReadIndex = requestSource.indexOf(
    "currentProofIndexTokenPayloadForRead",
    summaryReadIndex,
  );
  assert.ok(summaryReadIndex >= 0);
  assert.ok(tokenStateReadIndex > summaryReadIndex);
});

check("fresh public reads can use bounded canonical last-good summaries", async () => {
  const helper = isolatedFunction(
    API_PATH,
    "canonicalFreshReadCanUseLastGood",
    {
      CANONICAL_FRESH_LAST_GOOD_MAX_LAG_BLOCKS: 1,
      WORK_TOKEN_ID: "work-token-id",
      canonicalGateCanUseBoundedLastGood: (gate) =>
        gate?.ok === true &&
        gate.available === true &&
        gate.atTip !== true &&
        Number.isSafeInteger(Number(gate.indexedThroughBlock)) &&
        Number(gate.indexedThroughBlock) > 0 &&
        /^[0-9a-f]{64}$/u.test(
          String(gate.canonicalHash ?? "").trim().toLowerCase(),
        ) &&
        Number.isSafeInteger(Number(gate.lagBlocks)) &&
        Number(gate.lagBlocks) >= 0 &&
        Number(gate.lagBlocks) <= 1,
      canonicalSummarySnapshotReadGateApplies: (pathname) =>
        pathname === "/api/v1/work-floor",
      normalizeTokenScope: (value) =>
        String(value ?? "").trim().toUpperCase() === "WORK"
          ? "work-token-id"
          : String(value ?? "").trim().toLowerCase(),
    },
  );
  const gate = {
    atTip: false,
    available: true,
    canonicalHash: "9".repeat(64),
    indexedThroughBlock: 200,
    lagBlocks: 1,
    ok: true,
    summarySnapshotOk: true,
  };
  assert.equal(
    helper(new URL("https://wallet.proofofwork.me/api/v1/work-floor"), gate),
    true,
  );
  assert.equal(
    helper(
      new URL("https://wallet.proofofwork.me/api/v1/token?asset=WORK"),
      gate,
    ),
    true,
  );
  assert.equal(
    helper(
      new URL("https://wallet.proofofwork.me/api/v1/token?asset=WORK&wallet=1&address=sender"),
      gate,
    ),
    true,
    "wallet-scoped WORK reads may use the same bounded checkpoint",
  );
  assert.equal(
    helper(
      new URL("https://wallet.proofofwork.me/api/v1/token?asset=OTHER&wallet=1&address=sender"),
      gate,
    ),
    false,
    "non-WORK wallet reads stay exact-current",
  );
  assert.equal(
    helper(
      new URL("https://wallet.proofofwork.me/api/v1/token?asset=WORK"),
      { ...gate, lagBlocks: 2 },
    ),
    false,
  );
  assert.equal(
    helper(
      new URL("https://wallet.proofofwork.me/api/v1/work-floor"),
      { ...gate, summarySnapshotOk: false },
    ),
    false,
  );
});

