check("same-height pending membership versions the canonical Log snapshot", async () => {
  const readerKinds = /const PUBLIC_LOG_EVENT_KINDS = new Set\(\[([\s\S]*?)\]\);/u.exec(
    fileSource(READER_PATH),
  )?.[1];
  const backfillKinds = /const PUBLIC_LOG_EVENT_KINDS = new Set\(\[([\s\S]*?)\]\);/u.exec(
    fileSource(BACKFILL_PATH),
  )?.[1];
  const parseKinds = (source) =>
    [...String(source ?? "").matchAll(/"([^"]+)"/gu)]
      .map((match) => match[1])
      .sort();
  assert.deepEqual(parseKinds(backfillKinds), parseKinds(readerKinds));

  let rows = [
    {
      block_height: 100,
      block_time: "2026-07-14T17:00:00.000Z",
      created_at: "2026-07-14T17:00:00.000Z",
      event_id: "1",
      event_time: "2026-07-14T17:00:00.000Z",
      kind: "mail",
      payload_hash: "1".repeat(32),
      protocol: "pwm1",
      status: "confirmed",
      txid: "1".repeat(64),
      valid: true,
    },
  ];
  let fingerprintSql = "";
  const publicLogRelationalFingerprint = isolatedFunction(
    BACKFILL_PATH,
    "publicLogRelationalFingerprint",
    {
      NETWORK: "livenet",
      PUBLIC_LOG_EVENT_KINDS: new Set(["mail"]),
      createHash,
    },
  );
  const client = {
    async query(sql) {
      fingerprintSql = String(sql);
      return { rows };
    },
  };
  const before = await publicLogRelationalFingerprint(client);
  rows = [
    ...rows,
    {
      block_height: null,
      block_time: null,
      created_at: "2026-07-14T18:00:00.000Z",
      event_id: "2",
      event_time: "2026-07-14T18:00:00.000Z",
      kind: "mail",
      payload_hash: "2".repeat(32),
      protocol: "pwm1",
      status: "pending",
      txid: "2".repeat(64),
      valid: true,
    },
  ];
  const after = await publicLogRelationalFingerprint(client);
  assert.equal(before.count, 1);
  assert.equal(after.count, 2);
  assert.equal(after.pending, 1);
  assert.notEqual(after.hash, before.hash);
  const singlePendingRows = rows;
  rows = [
    ...singlePendingRows,
    {
      ...singlePendingRows[1],
      event_id: "3",
      payload_hash: "3".repeat(32),
    },
  ];
  const duplicated = await publicLogRelationalFingerprint(client);
  assert.equal(duplicated.count, 3);
  assert.equal(duplicated.pending, 2);
  assert.notEqual(duplicated.hash, after.hash);
  rows = singlePendingRows;
  const reconciled = await publicLogRelationalFingerprint(client);
  assert.deepEqual(reconciled, after);
  assert.match(fingerprintSql, /md5\(e\.payload::text\)/u);
  assert.doesNotMatch(fingerprintSql, /e\.updated_at/u);

  const runCycleSource = topLevelFunctionSource(WORKER_PATH, "runCycle");
  const pendingCheckpointSource = topLevelFunctionSource(
    WORKER_PATH,
    "assertWorkerPendingCheckpointCoversCoreTip",
  );
  assert.match(
    runCycleSource,
    /runCanonicalBeforePending\([\s\S]*runBackfillPhase\(backfillPhases\[0\]\)[\s\S]*publishCanonicalSummaryAtConfirmedCheckpoint\(\)[\s\S]*assertWorkerPendingCheckpointCoversCoreTip\(\s*canonicalProgress,\s*\);[\s\S]*pendingStatus = await refreshPendingStatusesSafely\(\);[\s\S]*runBackfillPhase\(backfillPhases\[1\]\)/u,
  );
  assert.match(
    pendingCheckpointSource,
    /readExactWorkerCoreTip\(\)[\s\S]*throwIfWorkerCoreTipAdvanced\([\s\S]*"pending-stage-preflight"[\s\S]*confirmed checkpoint no longer matches Core/u,
  );
  assert.doesNotMatch(
    runCycleSource,
    /async \(\) => \{\s*await runBackfillPhase\(backfillPhases\[1\]\);\s*pendingStatus = await refreshPendingStatusesSafely\(\);/u,
    "pending status maintenance must not stale the final Q16 pending witness",
  );
});

