check("confirmed token scope distinguishes resolved invalid and ambiguous evidence", async () => {
  const listingId = "a".repeat(64);
  const tokenId = "b".repeat(64);
  const buyTxid = "c".repeat(64);
  const delistTxid = "d".repeat(64);
  const unresolvedTxid = "e".repeat(64);
  const malformedTxid = "1".repeat(64);
  const mixedTxid = "2".repeat(64);
  const ambiguousListingId = "3".repeat(64);
  const ambiguousTxid = "4".repeat(64);
  const otherTokenId = "5".repeat(64);
  const blockHash = "6".repeat(64);
  const confirmedTokenVerifierScopeFromContext = isolatedFunction(
    API_PATH,
    "confirmedTokenVerifierScopeFromContext",
    {
      TOKEN_PROTOCOL_PREFIX: "pwt1:",
      canonicalTokenListingScopeEvidenceFromCore: async () => ({
        reason: "referenced-listing-does-not-exist",
        status: "deterministically-invalid",
      }),
      decodedProtocolMessages: (vout) => vout.map((output) => output.message),
      parseTokenPayload: (message) => message,
      transactionBlockHash: (tx) => tx.status?.block_hash ?? "",
      transactionBlockHeight: (tx) => tx.status?.block_height,
      transactionTxid: (tx) => tx.txid,
    },
  );
  const currentBlock = (tx) => ({
    ...tx,
    status: { block_hash: blockHash, block_height: 101, confirmed: true },
  });
  const context = {
    blockHash,
    coverageHeight: 101,
    transactions: [
      {
        txid: listingId,
        vout: [
          {
            message: {
              kind: "list",
              saleAuthorization: {
                registryAddress: "bc1registry",
                tokenId,
              },
            },
          },
        ],
      },
      currentBlock({
        txid: buyTxid,
        vout: [{ message: { kind: "buy", listingId } }],
      }),
      currentBlock({
        txid: delistTxid,
        vout: [{ message: { kind: "delist", listingId } }],
      }),
      currentBlock({
        txid: unresolvedTxid,
        vout: [
          {
            message: {
              kind: "buy",
              listingId: "f".repeat(64),
            },
          },
        ],
      }),
      currentBlock({
        txid: malformedTxid,
        vout: [{ message: null }],
      }),
      currentBlock({
        txid: mixedTxid,
        vout: [
          { message: null },
          { message: { kind: "send", tokenId } },
        ],
      }),
      {
        txid: ambiguousListingId,
        vout: [
          {
            message: {
              kind: "list",
              saleAuthorization: { tokenId },
            },
          },
          {
            message: {
              kind: "list",
              saleAuthorization: { tokenId: otherTokenId },
            },
          },
        ],
      },
      currentBlock({
        txid: ambiguousTxid,
        vout: [{ message: { kind: "buy", listingId: ambiguousListingId } }],
      }),
    ],
  };
  const buy = await confirmedTokenVerifierScopeFromContext(
    context,
    "livenet",
    buyTxid,
  );
  assert.equal(buy.scope, tokenId);
  assert.equal(buy.status, "resolved");
  const delist = await confirmedTokenVerifierScopeFromContext(
    context,
    "livenet",
    delistTxid,
  );
  assert.equal(delist.scope, tokenId);
  assert.equal(delist.status, "resolved");
  const invalid = await confirmedTokenVerifierScopeFromContext(
    context,
    "livenet",
    unresolvedTxid,
  );
  assert.equal(invalid.reason, "referenced-listing-is-not-canonical");
  assert.equal(invalid.status, "deterministically-invalid");
  const malformed = await confirmedTokenVerifierScopeFromContext(
    context,
    "livenet",
    malformedTxid,
  );
  assert.equal(malformed.status, "deterministically-invalid");
  const mixed = await confirmedTokenVerifierScopeFromContext(
    context,
    "livenet",
    mixedTxid,
  );
  assert.equal(mixed.scope, tokenId);
  assert.equal(mixed.status, "resolved");
  const ambiguous = await confirmedTokenVerifierScopeFromContext(
    context,
    "livenet",
    ambiguousTxid,
  );
  assert.equal(ambiguous.reason, "ambiguous-token-scope");
  assert.equal(ambiguous.status, "unresolved");
});

check("a canonical listing missing from DB context is unavailable, not invalid", async () => {
  const listingId = "7".repeat(64);
  const tokenId = "8".repeat(64);
  const listingBlockHash = "9".repeat(64);
  let mode = "canonical";
  const canonicalTokenListingScopeEvidenceFromCore = isolatedFunction(
    API_PATH,
    "canonicalTokenListingScopeEvidenceFromCore",
    {
      TOKEN_PROTOCOL_PREFIX: "pwt1:",
      bitcoinRpc: async (method) => {
        if (method === "getrawtransaction") {
          return mode === "missing"
            ? { error: { code: -5 }, ok: false }
            : {
                ok: true,
                result: {
                  blockhash: listingBlockHash,
                  confirmations: 2,
                  vout: [{ message: { kind: "list", saleAuthorization: { tokenId } } }],
                },
              };
        }
        if (method === "getblockheader") {
          return { ok: true, result: { height: 100 } };
        }
        if (method === "getblockhash") {
          return { ok: true, result: listingBlockHash };
        }
        throw new Error(`unexpected method ${method}`);
      },
      coreVoutToMempoolVout: (output) => output,
      decodedProtocolMessages: (vout) => vout.map((output) => output.message),
      parseTokenPayload: (message) => message,
    },
  );
  const unresolved = await canonicalTokenListingScopeEvidenceFromCore(
    { coverageHeight: 101 },
    "livenet",
    listingId,
  );
  assert.equal(unresolved.status, "unresolved");
  assert.equal(
    unresolved.reason,
    "canonical-listing-is-missing-from-index-context",
  );

  mode = "missing";
  const invalid = await canonicalTokenListingScopeEvidenceFromCore(
    { coverageHeight: 101 },
    "livenet",
    listingId,
  );
  assert.equal(invalid.status, "deterministically-invalid");
  assert.equal(invalid.reason, "referenced-listing-does-not-exist");
});

check("pre-V8 WORK listing scope is proven without restoring active state", async () => {
  const listingId = "8230a8c84264e5e56207c4eeec0a6e64daacafe7891326eeb4560c9736ccde30";
  const pendingTxid =
    "61c11eb4b90f03f238d645d144c6f6a4976e3928c1eff3f358e01d396307fa8c";
  const blockHash = "9".repeat(64);
  const rawPayload = "pwt1:list5:fixture";
  const scope = {
    authorizationVersion: "pwt-sale-v1",
    blockHash,
    blockHeight: 952_975,
    blockIndex: 527,
    listingId,
    model: "canonical-pre-v8-work-listing-scope-v1",
    network: "livenet",
    protocolVout: 1,
    rawPayloadSha256: createHash("sha256")
      .update(Buffer.from(rawPayload, "utf8"))
      .digest("hex"),
    recordOrdinal: 0,
    tokenId: WORK_TOKEN_ID,
  };
  const exactObjectKeys = (value, expectedKeys) =>
    Boolean(
      value &&
      typeof value === "object" &&
      !Array.isArray(value) &&
      JSON.stringify(Object.keys(value).sort()) ===
        JSON.stringify([...expectedKeys].sort()),
    );
  const historicalListingScope = isolatedFunction(
    API_PATH,
    "pendingWorkVerifierStageHistoricalListingScope",
    {
      PENDING_WORK_HISTORICAL_LISTING_AUTH_VERSIONS: [
        "pwt-sale-v1",
        "pwt-sale-v2",
        "pwt-sale-v3",
        "pwt-sale-v4",
        "pwt-sale-v5",
        "pwt-sale-v6",
        "pwt-sale-v7",
      ],
      PENDING_WORK_HISTORICAL_LISTING_SCOPE_MODEL:
        "canonical-pre-v8-work-listing-scope-v1",
      WORK_AMO_V8_ACTIVATION_HEIGHT: 960_601,
      pendingWorkVerifierStageExactObjectKeys: exactObjectKeys,
    },
  );
  assert.equal(
    JSON.stringify(historicalListingScope(scope)),
    JSON.stringify(scope),
  );
  assert.equal(
    historicalListingScope({ ...scope, blockHeight: 960_601 }),
    null,
  );
  assert.equal(
    historicalListingScope({ ...scope, authorizationVersion: "pwt-sale-v8" }),
    null,
  );

  const stageError = (code, message, details = {}) => {
    const error = new Error(message);
    error.details = { code, ...details };
    return error;
  };
  const historicalScopeMap = (scopes) =>
    new Map((Array.isArray(scopes) ? scopes : []).map((item) => [
      item.listingId,
      item,
    ]));
  const proveWorkScope = isolatedFunction(
    API_PATH,
    "pendingWorkVerifierStageProveWorkScope",
    {
      pendingWorkVerifierStageError: stageError,
      pendingWorkVerifierStageHistoricalListingScopeMap: historicalScopeMap,
    },
  );
  const transactionRecords = [{
    parsedMessages: [{ kind: "delist", listingId }],
    txid: pendingTxid,
  }];
  const emptyBase = { closedListings: [], listings: [] };
  const emptyMempool = { membership: new Set() };
  assert.doesNotThrow(() =>
    proveWorkScope(transactionRecords, emptyBase, emptyMempool, [scope])
  );
  assert.throws(
    () => proveWorkScope(transactionRecords, emptyBase, emptyMempool, []),
    (error) =>
      error.details?.code === "PENDING_WORK_STAGE_LISTING_PARENT_UNPROVEN",
  );
  assert.throws(
    () =>
      proveWorkScope(
        transactionRecords,
        emptyBase,
        { membership: new Set([listingId]) },
        [],
      ),
    (error) =>
      error.details?.code === "PENDING_WORK_STAGE_UNCONFIRMED_LISTING_PARENT",
  );

  let replayCalls = 0;
  let admissionCalls = 0;
  const decisions = isolatedFunction(
    API_PATH,
    "pendingWorkVerifierStageDecisions",
    {
      PENDING_WORK_HISTORICAL_LISTING_REASON:
        "Referenced pre-V8 ProofOfWork credit listing is historical, non-actionable audit state after AMO V8 activation.",
      PENDING_WORK_HISTORICAL_LISTING_REASON_CODE:
        "work-amo-v8-relic-listing-nonsettleable",
      pendingWorkVerifierStageCanonicalItem: (item) => item,
      pendingWorkVerifierStageHistoricalListingScopeMap: historicalScopeMap,
      pendingWorkVerifierStageInvalidEvidence: (
        _state,
        _transaction,
        parsed,
        _raw,
        historicalListingScopes,
      ) => ({
        historicalListingScopes,
        listingId: parsed.listingId,
        reasonCode: "work-amo-v8-relic-listing-nonsettleable",
      }),
      pendingWorkVerifierStageJsonClone: (value) => JSON.parse(JSON.stringify(value)),
      pendingWorkVerifierStageOrderConflictReason: () => "conflict",
      pendingWorkVerifierStageRecordHistoricalListingScopes: (
        record,
        historicalListings,
      ) => record.parsedMessages.flatMap((parsed) => {
        const item = historicalListings.get(parsed.listingId);
        return item ? [item] : [];
      }),
      pendingWorkVerifierStageRecordPositionKey: (value) =>
        `${value.protocolVout}:${value.recordOrdinal}`,
      pendingWorkVerifierStageReplayState: () => {
        replayCalls += 1;
        return {};
      },
      pendingWorkVerifierStageTransactionInvalidReason: async () => {
        admissionCalls += 1;
        return "";
      },
      tokenVerifierDeterministicInvalidReason: async () => "invalid",
      tokenVerifierItemsFromState: () => [],
      workAmoV5CanonicalPayloadCommitment: () => ({ sha256: "0".repeat(64) }),
    },
  );
  const rawRecord = {
    message: `pwt1:delist5:${listingId}`,
    protocolVout: 2,
    recordOrdinal: 0,
  };
  const [decision] = await decisions(
    emptyBase,
    [{
      mempoolCreatedAt: "2026-08-04T00:00:00.000Z",
      parsedMessages: transactionRecords[0].parsedMessages,
      records: [rawRecord],
      transaction: {},
      txid: pendingTxid,
    }],
    "livenet",
    961_061,
    [scope],
  );
  assert.equal(replayCalls, 0);
  assert.equal(admissionCalls, 0);
  assert.equal(decision.items.length, 1);
  assert.equal(decision.items[0].valid, false);
  assert.equal(decision.items[0].listingId, listingId);
  assert.equal(
    decision.items[0].reasonCode,
    "work-amo-v8-relic-listing-nonsettleable",
  );
  assert.equal(decision.items[0].historicalListingScopes[0].listingId, listingId);
  assert.match(decision.items[0].reason, /historical, non-actionable/u);
});

check("pending WORK admission defers retryable listing resolution to replay", async () => {
  const stageError = (code, message, details = {}) => {
    const error = new Error(message);
    error.details = { code, ...details };
    return error;
  };
  const txid = "a".repeat(64);
  const record = {
    transaction: { hex: "020000000001" },
    txid,
  };
  const reasonFor = (admissionError, deterministicReason) =>
    isolatedFunction(
      API_PATH,
      "pendingWorkVerifierStageTransactionInvalidReason",
      {
        WORK_AMO_V8_ACTIVATION_HEIGHT: 960_601,
        errorSummary: (error) =>
          error instanceof Error && error.message
            ? error.message
            : String(error),
        pendingWorkVerifierStageError: stageError,
        signedWorkMarketplaceWriteActions: async () => {
          throw admissionError;
        },
        tokenVerifierDeterministicInvalidReason: async () =>
          deterministicReason,
        workAmoV8ActiveMutationDecision: () => {
          throw new Error("admission decision should not run");
        },
        workAmoV8SignedMutationShape: () => ({ signed: true }),
      },
    );
  const retryable = new Error(
    "WORK marketplace listing resolution is temporarily unavailable; retry once the canonical listing read model catches up.",
  );
  retryable.statusCode = 503;
  retryable.details = {
    code: "WORK_MARKETPLACE_LISTING_RESOLUTION_UNAVAILABLE",
  };
  assert.equal(
    await reasonFor(retryable, "canonical invalid")(
      {},
      record,
      "livenet",
      962_499,
    ),
    "canonical invalid",
  );
  assert.equal(
    await reasonFor(retryable, "")({}, record, "livenet", 962_499),
    "",
    "a retryable listing-read miss may be decided valid only by canonical replay",
  );
  const unexpected = new Error("temporary dependency unavailable");
  unexpected.statusCode = 503;
  unexpected.details = { code: "OTHER_UNAVAILABLE" };
  await assert.rejects(
    () => reasonFor(unexpected, "")({}, record, "livenet", 962_499),
    (error) =>
      error.details?.code === "PENDING_WORK_STAGE_ADMISSION_UNAVAILABLE",
  );
});

check("historical WORK listing scope is rebound to exact Core bytes and position", async () => {
  const listingId = "8".repeat(64);
  const blockHash = "9".repeat(64);
  const rawPayload = "pwt1:list5:fixture";
  const scope = {
    authorizationVersion: "pwt-sale-v1",
    blockHash,
    blockHeight: 100,
    blockIndex: 2,
    listingId,
    model: "canonical-pre-v8-work-listing-scope-v1",
    network: "livenet",
    protocolVout: 1,
    rawPayloadSha256: createHash("sha256")
      .update(Buffer.from(rawPayload, "utf8"))
      .digest("hex"),
    recordOrdinal: 0,
    tokenId: WORK_TOKEN_ID,
  };
  let blockTxid = listingId;
  const stageError = (code, message, details = {}) => {
    const error = new Error(message);
    error.details = { code, ...details };
    return error;
  };
  const bindFromCore = isolatedFunction(
    API_PATH,
    "pendingWorkVerifierStageHistoricalListingScopeFromCore",
    {
      WORK_AMO_V8_ACTIVATION_HEIGHT: 101,
      bitcoinRpc: async (method) => {
        if (method === "getblockhash") return { ok: true, result: blockHash };
        if (method === "getblock") {
          return {
            ok: true,
            result: {
              hash: blockHash,
              height: 100,
              nTx: 3,
              tx: ["a".repeat(64), "b".repeat(64), blockTxid],
            },
          };
        }
        throw new Error(`unexpected method ${method}`);
      },
      canonicalRawProtocolRecordSetFromTransaction: () => ({
        records: [{
          message: rawPayload,
          protocol: "pwt1",
          protocolVout: 1,
          rawDecodeValid: true,
          recordOrdinal: 0,
        }],
      }),
      fetchTransactionFromBitcoinRpc: async () => ({
        hex: "00",
        status: { block_hash: blockHash, confirmed: true },
        txid: listingId,
      }),
      parseTokenPayload: () => ({
        kind: "list",
        saleAuthorization: {
          tokenId: WORK_TOKEN_ID,
          version: "pwt-sale-v1",
        },
      }),
      pendingWorkVerifierStageError: stageError,
      pendingWorkVerifierStageHistoricalListingScope: (value) => value,
      transactionBlockHash: (transaction) => transaction.status.block_hash,
      transactionConfirmed: (transaction) => transaction.status.confirmed,
      transactionTxid: (transaction) => transaction.txid,
    },
  );
  assert.deepEqual(
    await bindFromCore(scope, { blockHash: "c".repeat(64), height: 102 }),
    scope,
  );
  blockTxid = "d".repeat(64);
  await rejection(
    bindFromCore(scope, { blockHash: "c".repeat(64), height: 102 }),
    (error) =>
      error.details?.code === "PENDING_WORK_STAGE_LISTING_PARENT_UNPROVEN",
  );
  const stagePayloadSource = topLevelFunctionSource(
    API_PATH,
    "pendingWorkVerifierStagePayload",
  );
  assert.equal(
    (stagePayloadSource.match(
      /pendingWorkVerifierStageHistoricalListingScopes\(/gu,
    ) ?? []).length,
    2,
  );
  assert.match(
    stagePayloadSource,
    /isDeepStrictEqual\(\s*finalHistoricalListingScopes,\s*initialHistoricalListingScopes/u,
  );
  assert.match(
    topLevelFunctionSource(BACKFILL_PATH, "canonicalStoredWorkQ16PendingStage"),
    /stage\.codeVersion !== WORK_Q16_PENDING_STAGE_CODE_VERSION/u,
  );
  assert.match(
    topLevelFunctionSource(BACKFILL_PATH, "buildWorkQ16PendingStagePlan"),
    /parentStage\.codeVersion === WORK_Q16_PENDING_STAGE_CODE_VERSION/u,
  );
});

check("same-height verifier contexts are cached by exact block identity", async () => {
  const previousBlockHash = "a".repeat(64);
  const firstBlockHash = "b".repeat(64);
  const replacementBlockHash = "c".repeat(64);
  const keys = [];
  const loads = [];
  const canonicalVerifierContextFromCheckpoint = isolatedFunction(
    API_PATH,
    "canonicalVerifierContextFromCheckpoint",
    {
      cachedInternalVerifierState: async (key, loader) => {
        keys.push(key);
        return loader();
      },
      loadCanonicalVerifierContextFromCheckpoint: async (...args) => {
        loads.push(args);
        return { blockHash: args[2], coverageHeight: args[1] };
      },
      pruneInternalVerifierStateCache: () => {},
    },
  );
  await canonicalVerifierContextFromCheckpoint(
    "livenet",
    101,
    firstBlockHash,
    previousBlockHash,
  );
  await canonicalVerifierContextFromCheckpoint(
    "livenet",
    101,
    replacementBlockHash,
    previousBlockHash,
  );
  assert.equal(loads.length, 2);
  assert.notEqual(keys[0], keys[1]);
  assert.ok(keys[0].includes(firstBlockHash));
  assert.ok(keys[1].includes(replacementBlockHash));
});

check("confirmed verifier churn preserves unexpired shared pending replay state", () => {
  const sharedKey = "token:livenet:all";
  const expiredSharedKey = "id:livenet";
  const cache = new Map([
    [
      sharedKey,
      {
        expiresAt: Date.now() + 60_000,
        promise: Promise.resolve({}),
        settled: true,
      },
    ],
  ]);
  for (let index = 0; index < 15; index += 1) {
    cache.set(`token-complete:livenet:tx:${index}:h101:fixture`, {
      expiresAt: Date.now() + 60_000,
      promise: Promise.resolve({}),
      settled: true,
    });
  }
  const reusableInternalVerifierStateCacheKey = isolatedFunction(
    API_PATH,
    "reusableInternalVerifierStateCacheKey",
  );
  const pruneInternalVerifierStateCache = isolatedFunction(
    API_PATH,
    "pruneInternalVerifierStateCache",
    {
      INTERNAL_VERIFIER_STATE_CACHE: cache,
      reusableInternalVerifierStateCacheKey,
    },
  );

  pruneInternalVerifierStateCache();
  assert.equal(cache.size, 15);
  assert.equal(cache.has(sharedKey), true);
  assert.equal(cache.has("token-complete:livenet:tx:0:h101:fixture"), false);

  cache.set(expiredSharedKey, {
    expiresAt: Date.now() - 1,
    promise: Promise.resolve({}),
    settled: true,
  });
  pruneInternalVerifierStateCache();
  assert.equal(
    cache.has(expiredSharedKey),
    false,
    "cache priority must never extend an expired shared replay",
  );
});

check("canonical verifier rejects a replaced block before state hydration", async () => {
  const expectedBlockHash = "d".repeat(64);
  const replacementBlockHash = "e".repeat(64);
  let calls = 0;
  const canonicalVerifierCurrentBlock = isolatedFunction(
    API_PATH,
    "canonicalVerifierCurrentBlock",
    {
      bitcoinRpc: async (method) => {
        calls += 1;
        assert.equal(method, "getblockhash");
        return { ok: true, result: replacementBlockHash };
      },
    },
  );
  await rejection(
    canonicalVerifierCurrentBlock(
      "livenet",
      101,
      "f".repeat(64),
      expectedBlockHash,
    ),
    (error) => /does not match the requested canonical hash/u.test(error.message),
    "A same-height replacement must not reuse or hydrate the old block",
  );
  assert.equal(calls, 1);
});

