check("Core health requires one synced mainnet tip and exact unpruned txindex", () => {
  const height = 100;
  const blockHash = "7".repeat(64);
  const chainResponse = {
    ok: true,
    result: {
      bestblockhash: blockHash,
      blocks: height,
      chain: "main",
      headers: height,
      initialblockdownload: false,
      pruned: false,
      verificationprogress: 1,
    },
  };
  const indexResponse = {
    ok: true,
    result: {
      txindex: { best_block_height: height, synced: true },
    },
  };
  const exactCoreTipFromBlockchainInfo = isolatedFunction(
    API_PATH,
    "exactCoreTipFromBlockchainInfo",
  );
  const exactCoreNodeAuthority = isolatedFunction(
    API_PATH,
    "exactCoreNodeAuthority",
    { exactCoreTipFromBlockchainInfo },
  );
  assert.deepEqual(
    JSON.parse(JSON.stringify(
      exactCoreNodeAuthority(chainResponse, indexResponse),
    )),
    {
      blockHash,
      height,
      txindexHeight: height,
      verificationProgress: 1,
    },
  );
  for (const [label, changedChain, changedIndex] of [
    [
      "headers ahead",
      { ...chainResponse, result: { ...chainResponse.result, headers: 101 } },
      indexResponse,
    ],
    [
      "initial block download",
      {
        ...chainResponse,
        result: { ...chainResponse.result, initialblockdownload: true },
      },
      indexResponse,
    ],
    [
      "wrong chain",
      { ...chainResponse, result: { ...chainResponse.result, chain: "test" } },
      indexResponse,
    ],
    [
      "pruned node",
      { ...chainResponse, result: { ...chainResponse.result, pruned: true } },
      indexResponse,
    ],
    [
      "txindex behind",
      chainResponse,
      {
        ...indexResponse,
        result: {
          txindex: { best_block_height: height - 1, synced: true },
        },
      },
    ],
    [
      "txindex unsynced",
      chainResponse,
      {
        ...indexResponse,
        result: {
          txindex: { best_block_height: height, synced: false },
        },
      },
    ],
  ]) {
    assert.equal(
      exactCoreNodeAuthority(changedChain, changedIndex),
      null,
      label,
    );
  }
});

check("one exact-tip worker predicate preserves only healthy durable Q16 readiness", () => {
  const tipHeight = 100;
  const tipHash = "9".repeat(64);
  const finishedAt = "2026-08-04T12:00:00.000Z";
  const nowMs = Date.parse(finishedAt) + 30_000;
  const durableWorkPrecision = {
    era: "q16",
    replay: {
      era: "q16",
      mempoolCount: 3,
      mempoolSha256: "a".repeat(64),
      pendingMembershipCount: 2,
      pendingMembershipSha256: "b".repeat(64),
      pendingProjectionSha256: "c".repeat(64),
      ready: true,
      replayRequired: true,
      tipHash,
      tipHeight,
    },
  };
  const exactTipReadiness = isolatedFunction(
    API_PATH,
    "proofIndexWorkerExactTipReadiness",
    {
      PROOF_INDEX_HEALTH_MAX_AGE_MS: 120_000,
      WORK_AMO_V8_ACTIVATION_HEIGHT: 90,
      exactWorkAmoV8WorkerLastSuccessReadiness,
    },
  );
  const status = {
    indexedThroughBlock: tipHeight,
    network: "livenet",
    scan: { blockHash: tipHash, complete: true, tipHeight },
    worker: {
      lastSuccess: { finishedAt, workPrecision: durableWorkPrecision },
      lastSuccessAt: finishedAt,
      network: "livenet",
      ok: false,
      state: "canonical-phase-complete",
      workPrecision: {
        era: "q16",
        replay: {
          era: "q16",
          pendingRequired: true,
          ready: false,
          replayRequired: true,
        },
      },
    },
  };
  const ready = exactTipReadiness(status, {
    network: "livenet",
    nowMs,
    tipHash,
    tipHeight,
  });
  assert.equal(ready.ready, true);
  assert.equal(ready.proofSource, "last-success-confirmed-replay");
  assert.equal(ready.proofReady, true);
  for (const [label, changedStatus, options = {}] of [
    [
      "scan height",
      { ...status, scan: { ...status.scan, tipHeight: tipHeight - 1 } },
    ],
    [
      "worker error",
      { ...status, worker: { ...status.worker, error: "cycle failed" } },
    ],
    [
      "containment",
      {
        ...status,
        worker: { ...status.worker, noProgress: { active: true } },
      },
    ],
    [
      "precision recovery",
      {
        ...status,
        worker: {
          ...status.worker,
          workPrecision: {
            ...status.worker.workPrecision,
            readinessRecoveryRequired: true,
          },
        },
      },
    ],
    [
      "failed state",
      { ...status, worker: { ...status.worker, state: "failed-retrying" } },
    ],
    ["stale proof", status, { nowMs: nowMs + 120_001 }],
  ]) {
    assert.equal(
      exactTipReadiness(changedStatus, {
        network: "livenet",
        nowMs,
        tipHash,
        tipHeight,
        ...options,
      }).ready,
      false,
      label,
    );
  }
  assert.equal(
    exactTipReadiness(status, {
      network: "livenet",
      nowMs,
      tipHash: "8".repeat(64),
      tipHeight,
    }).ready,
    false,
    "a changed Core hash invalidates the durable proof",
  );
  const confirmedOnlyStatus = {
    ...status,
    worker: {
      ...status.worker,
      lastSuccess: {
        finishedAt,
        workPrecision: {
          era: "q16",
          replay: {
            confirmed: {
              era: "q16",
              ready: true,
              replayRequired: true,
              tipHash,
              tipHeight,
            },
            era: "q16",
            pendingError: "pending witness unavailable",
            pendingReady: false,
            pendingRequired: true,
            ready: false,
            replayRequired: true,
          },
        },
      },
      ok: true,
      state: "idle",
      finishedAt,
      workPrecision: {
        era: "q16",
        replay: {
          confirmed: {
            era: "q16",
            ready: true,
            replayRequired: true,
            tipHash,
            tipHeight,
          },
          era: "q16",
          pendingReady: false,
          pendingRequired: true,
          ready: false,
          replayRequired: true,
        },
      },
    },
  };
  const confirmedOnlyReady = exactTipReadiness(confirmedOnlyStatus, {
    network: "livenet",
    nowMs,
    tipHash,
    tipHeight,
  });
  assert.equal(confirmedOnlyReady.ready, true);
  assert.equal(confirmedOnlyReady.proofSource, "idle-confirmed-replay");
  assert.equal(confirmedOnlyReady.proofReady, true);
  const durableOnlyIdleStatus = {
    ...status,
    worker: {
      ...status.worker,
      finishedAt: undefined,
      lastSuccess: {
        finishedAt,
        workPrecision: {
          era: "q16",
          replay: {
            confirmed: {
              era: "q16",
              ready: true,
              replayRequired: true,
              tipHash,
              tipHeight,
            },
            era: "q16",
            pendingError: "pending witness unavailable",
            pendingReady: false,
            pendingRequired: true,
            ready: false,
            replayRequired: true,
          },
        },
      },
      ok: true,
      state: "idle",
      workPrecision: {
        era: "q16",
        replay: {
          era: "q16",
          pendingReady: false,
          pendingRequired: true,
          ready: false,
          replayRequired: true,
        },
      },
    },
  };
  const durableOnlyReady = exactTipReadiness(durableOnlyIdleStatus, {
    network: "livenet",
    nowMs,
    tipHash,
    tipHeight,
  });
  assert.equal(durableOnlyReady.ready, true);
  assert.equal(durableOnlyReady.proofSource, "idle-confirmed-replay");
  assert.equal(durableOnlyReady.proofReady, true);
  assert.equal(
    exactTipReadiness(
      {
        ...durableOnlyIdleStatus,
        worker: {
          ...durableOnlyIdleStatus.worker,
          lastSuccess: {
            ...durableOnlyIdleStatus.worker.lastSuccess,
            workPrecision: {
              era: "q16",
              replay: {
                era: "q16",
                pendingError: "pending witness unavailable",
                pendingReady: false,
                pendingRequired: true,
                ready: false,
                replayRequired: true,
              },
            },
          },
        },
      },
      { network: "livenet", nowMs, tipHash, tipHeight },
    ).ready,
    false,
    "idle durable-only readiness requires an explicit confirmed proof",
  );
  const transientConfirmedStatus = {
    ...status,
    worker: {
      ...status.worker,
      workPrecision: {
        era: "q16",
        replay: {
          confirmed: {
            era: "q16",
            ready: true,
            replayRequired: true,
            tipHash,
            tipHeight,
          },
          era: "q16",
          pendingRequired: true,
          ready: false,
          replayRequired: true,
        },
      },
    },
  };
  const transientConfirmedReady = exactTipReadiness(
    transientConfirmedStatus,
    {
      network: "livenet",
      nowMs,
      tipHash,
      tipHeight,
    },
  );
  assert.equal(transientConfirmedReady.ready, true);
  assert.equal(
    transientConfirmedReady.proofSource,
    "current-confirmed-replay",
  );
  assert.equal(
    exactTipReadiness(
      {
        ...transientConfirmedStatus,
        worker: {
          ...transientConfirmedStatus.worker,
          error: "pending backfill failed",
        },
      },
      {
        network: "livenet",
        nowMs,
        tipHash,
        tipHeight,
      },
    ).ready,
    false,
    "a transient confirmed proof cannot bypass an active worker error",
  );
});

check("summary catch-up does not brown out current relational reads", async () => {
  const blockHash = "a".repeat(64);
  let summaryIndexedThroughBlock = 99;
  let chainInfo = {
    bestblockhash: blockHash,
    blocks: 100,
    chain: "main",
    headers: 100,
    initialblockdownload: false,
    verificationprogress: 1,
  };
  let busyTipResponses = 1;
  let tipProbeCalls = 0;
  const exactCoreTipFromBlockchainInfo = isolatedFunction(
    API_PATH,
    "exactCoreTipFromBlockchainInfo",
  );
  const proofIndexWorkerExactTipReadiness = isolatedFunction(
    API_PATH,
    "proofIndexWorkerExactTipReadiness",
    {
      PROOF_INDEX_HEALTH_MAX_AGE_MS: 120_000,
      WORK_AMO_V8_ACTIVATION_HEIGHT: 200,
      exactWorkAmoV8WorkerLastSuccessReadiness,
    },
  );
  const summarySnapshotCoversCanonicalReadModels = isolatedFunction(
    API_PATH,
    "summarySnapshotCoversCanonicalReadModels",
  );
  const loadCanonicalPublicReadGate = isolatedFunction(
    API_PATH,
    "loadCanonicalPublicReadGate",
    {
      CANONICAL_PUBLIC_READ_GATE_TIP_ATTEMPTS: 3,
      CANONICAL_PUBLIC_READ_GATE_TIP_RETRY_DELAY_MS: 0,
      PROOF_INDEX_HEALTH_MAX_AGE_MS: 120_000,
      PROOF_INDEX_REQUIRED: true,
      bitcoinRpc: async () => {
        tipProbeCalls += 1;
        if (busyTipResponses > 0) {
          busyTipResponses -= 1;
          return {
            error: { message: "Work queue depth exceeded" },
            ok: false,
          };
        }
        return {
          ok: true,
          result: chainInfo,
        };
      },
      exactCoreTipFromBlockchainInfo,
      proofIndexCanonicalStateMetaPayload: async () => ({
        fault: {},
        rebuild: { active: false, status: "complete" },
      }),
      proofIndexOperationalStatusPayload: async () => ({
        indexedThroughBlock: 100,
        network: "livenet",
        readModels: {
          confirmedEvents: { count: 10, maxBlock: 99 },
          confirmedIds: { count: 1, maxBlock: 90 },
          confirmedTransfers: { count: 1, maxBlock: 95 },
        },
        scan: { blockHash, complete: true, tipHeight: 100 },
        summarySnapshot: {
          blockHash,
          eligible: true,
          indexedThroughBlock: summaryIndexedThroughBlock,
        },
        worker: {
          lastSuccessAt: new Date().toISOString(),
          network: "livenet",
          ok: true,
        },
      }),
      proofIndexWorkerExactTipReadiness,
      summarySnapshotCoversCanonicalReadModels,
    },
  );
  const gate = await loadCanonicalPublicReadGate("livenet");
  assert.equal(tipProbeCalls, 2);
  assert.equal(gate.ok, true);
  assert.equal(gate.summarySnapshotOk, false);
  chainInfo = { ...chainInfo, initialblockdownload: true };
  assert.equal(
    (await loadCanonicalPublicReadGate("livenet")).available,
    false,
    "initial block download must close canonical public availability",
  );
  chainInfo = {
    ...chainInfo,
    headers: 101,
    initialblockdownload: false,
  };
  assert.equal(
    (await loadCanonicalPublicReadGate("livenet")).available,
    false,
    "headers ahead of blocks must close canonical public availability",
  );
  chainInfo = { ...chainInfo, headers: 100 };
  summaryIndexedThroughBlock = 100;
  const changedGate = await loadCanonicalPublicReadGate("livenet");
  assert.equal(changedGate.summarySnapshotOk, true);

  const summaryGate = isolatedFunction(
    API_PATH,
    "canonicalSummarySnapshotReadGateApplies",
  );
  assert.equal(summaryGate("/api/v1/ids/inception"), false);
  assert.equal(summaryGate("/api/v1/token-history"), false);
  assert.equal(summaryGate("/api/v1/work-floor"), true);
  assert.equal(summaryGate("/api/v1/work-summary"), true);
  assert.equal(summaryGate("/api/v1/marketplace-summary"), true);
  assert.equal(summaryGate("/api/v1/infinity-summary"), true);
  assert.equal(summaryGate("/api/v1/growth-summary"), true);
});

