check("AMO V5 generic activation seeds preserve exact integers and reject lossy JSON numbers", () => {
  const exactSeedInteger = isolatedFunction(
    WORK_AMO_V5_MIGRATION_PATH,
    "canonicalWorkAmoExactSeedInteger",
  );
  const jsonNumbersAreExact = isolatedFunction(
    WORK_AMO_V5_MIGRATION_PATH,
    "canonicalWorkAmoJsonNumbersAreExact",
  );
  const exactGenericSeedProjection = isolatedFunction(
    WORK_AMO_V5_MIGRATION_PATH,
    "canonicalWorkAmoExactGenericSeedProjection",
    {
      WORK_AMO_V5_RESERVED_TOKEN_IDS: new Set([
        WORK_AMO_V5_POWB_TOKEN_ID,
        WORK_AMO_V5_INCB_TOKEN_ID,
      ]),
      WORK_TOKEN_ID,
      canonicalWorkAmoExactSeedInteger: exactSeedInteger,
      canonicalWorkAmoJsonNumbersAreExact: jsonNumbersAreExact,
      normalizeWorkAmoV5RawGenericState,
    },
  );
  const registryAddress =
    "1F1p9UEHuH5KTFR7Zsx93Khdrqhj6t5nFv";
  const genericTokenId = "d".repeat(64);
  const hugeSupply = "900719925474099312345678901234567890";
  const hugeMaximum = "900719925474099412345678901234567890";
  const strictSeed = {
    holders: [
      {
        address: registryAddress,
        balance: hugeSupply,
        tokenId: genericTokenId,
      },
      {
        address: registryAddress,
        balance: "123456789012345678901234567890",
        tokenId: WORK_AMO_V5_POWB_TOKEN_ID,
      },
      {
        address: registryAddress,
        balance: "223456789012345678901234567890",
        tokenId: WORK_AMO_V5_INCB_TOKEN_ID,
      },
    ],
    listings: [],
    tokens: [
      {
        confirmedSupplyAtoms: hugeSupply,
        maxSupply: hugeMaximum,
        mintAmount: "9007199254740995",
        mintPriceSats: "9007199254740997",
        registryAddress,
        ticker: "EXACT",
        tokenId: genericTokenId,
      },
      {
        confirmedSupplyAtoms: "123456789012345678901234567890",
        maxSupply: null,
        maxSupplyModel: "uncapped",
        mintAmount: "100000000000000000001",
        mintPriceSats: "546",
        registryAddress,
        ticker: "POWB",
        tokenId: WORK_AMO_V5_POWB_TOKEN_ID,
      },
      {
        confirmedSupplyAtoms: "223456789012345678901234567890",
        maxSupply: null,
        maxSupplyModel: "uncapped",
        mintAmount: "200000000000000000001",
        mintPriceSats: "546",
        registryAddress,
        ticker: "INCB",
        tokenId: WORK_AMO_V5_INCB_TOKEN_ID,
      },
    ],
  };
  const strictProjection = exactGenericSeedProjection(strictSeed);
  assert.equal(
    strictProjection.tokens.find(
      (token) => token.tokenId === genericTokenId,
    )?.confirmedSupplyAtoms,
    hugeSupply,
  );
  assert.equal(
    strictProjection.holders.find(
      (holder) => holder.tokenId === genericTokenId,
    )?.balance,
    hugeSupply,
  );

  const safeLegacySeed = {
    holders: [{
      address: registryAddress,
      balance: 900,
      tokenId: genericTokenId,
    }],
    listings: [],
    tokens: [{
      confirmedSupplyAtoms: 900,
      maxSupply: 1_000,
      mintAmount: 10,
      mintPriceSats: 546,
      registryAddress,
      ticker: "LEGACY",
      tokenId: genericTokenId,
    }],
  };
  assert.throws(
    () => exactGenericSeedProjection(safeLegacySeed),
    /inexact JSON number|definition/u,
  );
  const legacyProjection = exactGenericSeedProjection(
    safeLegacySeed,
    { allowSafeLegacyNumbers: true },
  );
  assert.equal(legacyProjection.tokens[0].maxSupply, "1000");
  assert.equal(legacyProjection.holders[0].balance, "900");

  for (const unsafeValue of [
    Number.MAX_SAFE_INTEGER + 1,
    1.5,
  ]) {
    assert.throws(
      () =>
        exactGenericSeedProjection(
          {
            ...safeLegacySeed,
            tokens: [{
              ...safeLegacySeed.tokens[0],
              mintPriceSats: unsafeValue,
            }],
          },
          { allowSafeLegacyNumbers: true },
        ),
      /inexact JSON number|definition/u,
    );
  }
  for (const bondTokenId of [
    WORK_AMO_V5_POWB_TOKEN_ID,
    WORK_AMO_V5_INCB_TOKEN_ID,
  ]) {
    const bondSeed = {
      holders: [{
        address: registryAddress,
        balance: 1,
        tokenId: bondTokenId,
      }],
      listings: [],
      tokens: [{
        confirmedSupplyAtoms: 1,
        maxSupply: null,
        maxSupplyModel: "uncapped",
        mintAmount: 1,
        mintPriceSats: 546,
        registryAddress,
        ticker:
          bondTokenId === WORK_AMO_V5_POWB_TOKEN_ID
            ? "POWB"
            : "INCB",
        tokenId: bondTokenId,
      }],
    };
    assert.throws(
      () =>
        exactGenericSeedProjection(
          bondSeed,
          { allowSafeLegacyNumbers: true },
        ),
      /definition|holder/u,
    );
  }
});

check("AMO V5 readiness coalesces only identical exact checkpoints", async () => {
  const checkpointKey = isolatedFunction(
    READER_PATH,
    "workAmoReplayReadinessCheckpointKey",
  );
  const readinessRequest = isolatedFunction(
    READER_PATH,
    "workAmoReplayReadinessRequest",
    {
      workAmoReplayReadinessCheckpointKey: checkpointKey,
    },
  );
  const singleFlight = isolatedFunction(
    READER_PATH,
    "exactCheckpointSingleFlight",
  );
  const deepFreezeSnapshot = isolatedFunction(
    READER_PATH,
    "deepFreezeReadinessSnapshot",
  );
  const exactPositive = isolatedFunction(
    READER_PATH,
    "workAmoReplayReadinessResultIsExactPositive",
  );
  const rememberReady = isolatedFunction(
    READER_PATH,
    "rememberExactCheckpointReadiness",
  );
  const readinessWithCache = isolatedFunction(
    READER_PATH,
    "exactCheckpointReadinessWithCache",
    {
      exactCheckpointSingleFlight: singleFlight,
      deepFreezeReadinessSnapshot: deepFreezeSnapshot,
      rememberExactCheckpointReadiness: rememberReady,
      workAmoReplayReadinessResultIsExactPositive: exactPositive,
    },
  );
  const tipHash = "a".repeat(64);
  assert.equal(
    checkpointKey("livenet", {
      throughBlockHash: tipHash.toUpperCase(),
      throughHeight: 960_000,
    }),
    `livenet:960000:${tipHash}`,
  );
  const mutableOptions = {
    throughBlockHash: tipHash,
    throughHeight: 960_000,
  };
  const snapshottedRequest = readinessRequest("livenet", mutableOptions);
  mutableOptions.throughBlockHash = "b".repeat(64);
  mutableOptions.throughHeight = 960_001;
  assert.equal(
    snapshottedRequest.checkpointKey,
    `livenet:960000:${tipHash}`,
  );
  assert.equal(snapshottedRequest.options.throughBlockHash, tipHash);
  assert.equal(snapshottedRequest.options.throughHeight, 960_000);
  assert.equal(Object.isFrozen(snapshottedRequest), true);
  assert.equal(Object.isFrozen(snapshottedRequest.options), true);
  assert.equal(
    readinessRequest("livenet", {
      force: true,
      throughBlockHash: tipHash,
      throughHeight: 960_000,
    }).checkpointKey,
    "",
  );
  assert.equal(
    readinessRequest("livenet", {
      singleFlightBypass: true,
      throughBlockHash: tipHash,
      throughHeight: 960_000,
    }).checkpointKey,
    "",
  );
  for (const options of [
    {},
    { throughBlockHash: "invalid", throughHeight: 960_000 },
    { throughBlockHash: tipHash, throughHeight: 0 },
    { throughBlockHash: tipHash, throughHeight: 1.5 },
  ]) {
    assert.equal(checkpointKey("livenet", options), "");
  }

  const inFlight = new Map();
  let sameKeyLoads = 0;
  let releaseSameKey;
  const sameKeyGate = new Promise((resolve) => {
    releaseSameKey = resolve;
  });
  const loadSameKey = async () => {
    sameKeyLoads += 1;
    await sameKeyGate;
    return "ready";
  };
  const first = singleFlight(inFlight, "same", loadSameKey);
  const second = singleFlight(inFlight, "same", loadSameKey);
  await Promise.resolve();
  assert.equal(sameKeyLoads, 1);
  releaseSameKey();
  assert.deepEqual(await Promise.all([first, second]), ["ready", "ready"]);
  assert.equal(inFlight.size, 0);

  let distinctKeyLoads = 0;
  const [left, right] = await Promise.all([
    singleFlight(inFlight, "left", async () => {
      distinctKeyLoads += 1;
      return "left";
    }),
    singleFlight(inFlight, "right", async () => {
      distinctKeyLoads += 1;
      return "right";
    }),
  ]);
  assert.equal(distinctKeyLoads, 2);
  assert.deepEqual([left, right], ["left", "right"]);
  assert.equal(inFlight.size, 0);

  await assert.rejects(
    singleFlight(inFlight, "retry", async () => {
      throw new Error("expected readiness failure");
    }),
    /expected readiness failure/u,
  );
  assert.equal(inFlight.has("retry"), false);
  assert.equal(
    await singleFlight(inFlight, "retry", async () => "recovered"),
    "recovered",
  );

  const exactResult = {
    canonicalTip: 960_000,
    canonicalTipBlockHash: tipHash,
    indexReady: true,
    ready: true,
    requestedThroughBlockHash: tipHash,
    requestedThroughHeight: 960_000,
    requestedTipReady: true,
    declaration: { txid: "c".repeat(64) },
    reasons: [],
    throughHeight: 960_000,
  };
  const exactOptions = {
    throughBlockHash: tipHash,
    throughHeight: 960_000,
  };
  assert.equal(exactPositive(exactResult, exactOptions), true);
  for (const changed of [
    { ready: false },
    { indexReady: false },
    { requestedTipReady: false },
    { canonicalTip: 960_001 },
    { canonicalTipBlockHash: "b".repeat(64) },
    { requestedThroughBlockHash: "b".repeat(64) },
    { requestedThroughHeight: 960_001 },
    { throughHeight: 960_001 },
  ]) {
    assert.equal(
      exactPositive({ ...exactResult, ...changed }, exactOptions),
      false,
    );
  }

  const readyCache = new Map();
  rememberReady(readyCache, "first", exactResult);
  rememberReady(readyCache, "second", exactResult);
  rememberReady(readyCache, "third", exactResult);
  assert.deepEqual([...readyCache.keys()], ["second", "third"]);
  rememberReady(readyCache, "second", exactResult);
  assert.deepEqual([...readyCache.keys()], ["third", "second"]);

  let positiveLoads = 0;
  const positiveReadyCache = new Map();
  const loadPositive = async () => {
    positiveLoads += 1;
    return exactResult;
  };
  const positiveRequest = {
    checkpointKey: "positive",
    inFlight: new Map(),
    load: loadPositive,
    options: exactOptions,
    readyCache: positiveReadyCache,
  };
  const firstPositive = await readinessWithCache(positiveRequest);
  const secondPositive = await readinessWithCache(positiveRequest);
  assert.equal(positiveLoads, 1);
  assert.equal(firstPositive, secondPositive);
  assert.equal(Object.isFrozen(firstPositive), true);
  assert.equal(Object.isFrozen(firstPositive.declaration), true);
  assert.equal(Object.isFrozen(firstPositive.reasons), true);
  assert.throws(
    () => {
      firstPositive.ready = false;
    },
    TypeError,
  );
  assert.throws(() => firstPositive.reasons.push("poisoned"), TypeError);
  assert.throws(
    () => {
      firstPositive.declaration.txid = "d".repeat(64);
    },
    TypeError,
  );
  assert.equal(secondPositive.ready, true);
  assert.equal(secondPositive.reasons.length, 0);
  assert.equal(secondPositive.declaration.txid, "c".repeat(64));

  const differentTipHash = "b".repeat(64);
  const differentTipResult = {
    ...exactResult,
    canonicalTipBlockHash: differentTipHash,
    requestedThroughBlockHash: differentTipHash,
  };
  const differentTipOptions = {
    ...exactOptions,
    throughBlockHash: differentTipHash,
  };
  await readinessWithCache({
    ...positiveRequest,
    checkpointKey: "positive-different-hash",
    load: async () => {
      positiveLoads += 1;
      return differentTipResult;
    },
    options: differentTipOptions,
  });
  assert.equal(positiveLoads, 2);
  assert.deepEqual(
    [...positiveReadyCache.keys()],
    ["positive", "positive-different-hash"],
  );

  let negativeLoads = 0;
  const negativeRequest = {
    checkpointKey: "negative",
    inFlight: new Map(),
    load: async () => {
      negativeLoads += 1;
      return { ...exactResult, ready: false };
    },
    options: exactOptions,
    readyCache: new Map(),
  };
  await readinessWithCache(negativeRequest);
  await readinessWithCache(negativeRequest);
  assert.equal(negativeLoads, 2);
});

check("AMO V8 request coalescing binds exact reader identity and live inputs", () => {
  const statusCacheKey = isolatedFunction(
    API_PATH,
    "workAmoV8StatusCacheKey",
  );
  const readinessIdentity = isolatedFunction(
    API_PATH,
    "workAmoV8MigrationReadinessIdentity",
    {
      workAmoV8MigrationReadinessIdentities: new WeakMap(),
      workAmoV8MigrationReadinessIdentitySequence: 0,
    },
  );
  const liveProbeKey = isolatedFunction(
    API_PATH,
    "workAmoV8ExactLiveProbeKey",
  );
  const declarationBlockHash = "a".repeat(64);
  const tipHash = "b".repeat(64);
  const expectedDeclaration = {
    activationHeight: 960_601,
    authorityScriptPubKey: `5120${"c".repeat(64)}`,
    blockHash: declarationBlockHash,
    blockHeight: 960_600,
    blockTransactionIndex: 2_369,
    minimumPaymentSats: 546,
    payloadBytes: 128,
    payloadSha256: "d".repeat(64),
    protocolVout: 1,
    recordOrdinal: 0,
    registryAddress: "bc1ptestregistry",
    registryPaymentVout: 0,
    txid: "e".repeat(64),
  };
  const persistentEvidenceForDeclaration = isolatedFunction(
    API_PATH,
    "workAmoV8PersistentDeclarationEvidence",
    {
      validateWorkAmoV8DeclarationEvidence: (evidence, options) => ({
        valid:
          evidence?.canonical === true &&
          evidence?.confirmed === true &&
          evidence?.evidenceComplete === true &&
          evidence?.txid === options.expectedDeclaration.txid &&
          Number(evidence?.minimumPaymentSats) ===
            options.expectedDeclaration.minimumPaymentSats,
      }),
    },
  );
  const persistentEvidence = persistentEvidenceForDeclaration(
    {
      coreVerified: true,
      evidenceComplete: true,
      indexVerified: true,
      reached: true,
    },
    expectedDeclaration,
  );
  assert.equal(persistentEvidence.confirmed, true);
  assert.equal(persistentEvidence.canonical, true);
  assert.equal(persistentEvidence.evidenceComplete, true);
  assert.equal(
    persistentEvidence.minimumPaymentSats,
    expectedDeclaration.minimumPaymentSats,
  );
  assert.equal(
    persistentEvidenceForDeclaration(
      {
        coreVerified: true,
        evidenceComplete: false,
        indexVerified: true,
        reached: true,
      },
      expectedDeclaration,
    ),
    null,
  );
  const liveMempoolSnapshot = {
    count: 7,
    model: "canonical-core-mempool-txid-set-v1",
    sha256: "f".repeat(64),
  };
  const workerReadiness = {
    era: "q16",
    finishedAt: "2026-08-02T20:00:00.000Z",
    mempoolCount: 7,
    mempoolSha256: "f".repeat(64),
    pendingMembershipCount: 2,
    pendingMembershipSha256: "1".repeat(64),
    pendingProjectionSha256: "2".repeat(64),
    proofSource: "idle-last-success",
    ready: true,
    state: "idle",
    tipHash,
    tipHeight: 960_768,
  };
  const inputs = {
    expectedDeclaration,
    liveMempoolSnapshot,
    migrationReadinessIdentity: "exact-readiness-1",
    network: "livenet",
    networkValueBeforeQ8: "123456789",
    tipHash,
    tipHeight: 960_768,
    workerReadiness,
  };
  const liveProbe = {
    liveMempoolSnapshot,
    tipHash,
    tipHeight: 960_768,
    workerReadiness,
  };
  const changedMempoolProbe = {
    ...liveProbe,
    liveMempoolSnapshot: {
      ...liveMempoolSnapshot,
      count: 8,
      sha256: "3".repeat(64),
    },
  };
  assert.notEqual(liveProbeKey(liveProbe), liveProbeKey(changedMempoolProbe));
  assert.equal(
    liveProbeKey(liveProbe, { includeMempool: false }),
    liveProbeKey(changedMempoolProbe, { includeMempool: false }),
  );
  const changedWorkerTimestampProbe = {
    ...liveProbe,
    workerReadiness: {
      ...workerReadiness,
      finishedAt: "2026-08-02T20:00:01.000Z",
      pendingProjectionSha256: "6".repeat(64),
    },
  };
  assert.equal(
    liveProbeKey(liveProbe, { includeMempool: false }),
    liveProbeKey(changedWorkerTimestampProbe, { includeMempool: false }),
  );
  const notReadyWorkerProbe = {
    ...liveProbe,
    workerReadiness: {
      ...workerReadiness,
      ready: false,
    },
  };
  assert.notEqual(
    liveProbeKey(liveProbe, { includeMempool: false }),
    liveProbeKey(notReadyWorkerProbe, { includeMempool: false }),
  );
  const readinessKey = statusCacheKey(inputs);
  assert.notEqual(readinessKey, "");
  for (const changedInputs of [
    {
      ...inputs,
      migrationReadinessIdentity: "exact-readiness-2",
    },
    {
      ...inputs,
      expectedDeclaration: {
        ...expectedDeclaration,
        txid: "3".repeat(64),
      },
    },
    {
      ...inputs,
      liveMempoolSnapshot: {
        ...liveMempoolSnapshot,
        sha256: "4".repeat(64),
      },
    },
    {
      ...inputs,
      networkValueBeforeQ8: "123456790",
    },
    {
      ...inputs,
      tipHash: "5".repeat(64),
      workerReadiness: {
        ...workerReadiness,
        tipHash: "5".repeat(64),
      },
    },
    {
      ...inputs,
      workerReadiness: {
        ...workerReadiness,
        finishedAt: "2026-08-02T20:00:01.000Z",
      },
    },
    {
      ...inputs,
      workerReadiness: {
        ...workerReadiness,
        pendingProjectionSha256: "6".repeat(64),
      },
    },
  ]) {
    assert.notEqual(statusCacheKey(changedInputs), readinessKey);
  }
  assert.equal(
    statusCacheKey({
      ...inputs,
      expectedDeclaration: {
        ...expectedDeclaration,
        blockHash: "invalid",
      },
    }),
    "",
  );
  assert.notEqual(
    statusCacheKey({
      ...inputs,
      workerReadiness: { ...workerReadiness, ready: false },
    }),
    readinessKey,
  );
  assert.equal(
    statusCacheKey({
      ...inputs,
      migrationReadinessIdentity: "",
    }),
    "",
  );
  const exactReadiness = {
    active: true,
    canonical: true,
    confirmed: true,
    evidenceComplete: true,
    exactTipReady: true,
    parityReady: true,
    pendingReady: true,
    ready: true,
    replayReady: true,
  };
  const firstIdentity = readinessIdentity(exactReadiness);
  assert.match(firstIdentity, /^exact-readiness-[1-9][0-9]*$/u);
  assert.equal(readinessIdentity(exactReadiness), firstIdentity);
  assert.notEqual(readinessIdentity({ ...exactReadiness }), firstIdentity);
  assert.match(
    readinessIdentity({
      ...exactReadiness,
      active: false,
      pendingReady: false,
      ready: false,
    }),
    /^exact-readiness-[1-9][0-9]*$/u,
  );
  assert.equal(
    readinessIdentity({ ...exactReadiness, replayReady: false }),
    "",
  );

  const apiSource = readFileSync(API_PATH, "utf8");
  assert.doesNotMatch(apiSource, /WORK_AMO_V8_STATUS_CACHE_TTL_MS/u);
  assert.doesNotMatch(apiSource, /workAmoV8StatusCache\.payload/u);
  const metadataSource = topLevelFunctionSource(
    API_PATH,
    "workAmoV8Metadata",
  );
  assert.match(
    metadataSource,
    /proofIndexWorkPrecisionV2MigrationReadiness[\s\S]*workAmoV8StatusCacheKey[\s\S]*workAmoV8MetadataSingleFlight/u,
  );
  assert.match(
    metadataSource,
    /workAmoV8ExactReadinessSweep[\s\S]*pendingValidThrough/u,
  );
  assert.match(
    metadataSource,
    /const durableActivationLatch =[\s\S]*configuredActivationLatch\?\.reached === true[\s\S]*configuredPinsMatchPersistent[\s\S]*persistentActivationLatch\?\.reached === true[\s\S]*const persistentDeclarationEvidence =[\s\S]*workAmoV8PersistentDeclarationEvidence\([\s\S]*durableActivationLatch[\s\S]*const liveEvidenceReady =[\s\S]*validateWorkAmoV8DeclarationEvidence[\s\S]*const statusEvidence =[\s\S]*persistentDeclarationEvidence \?\? null[\s\S]*const combinedEvidence = statusEvidence/u,
  );
  const sweepSource = topLevelFunctionSource(
    API_PATH,
    "workAmoV8ExactReadinessSweep",
  );
  assert.match(
    sweepSource,
    /workAmoV8ExactLiveProbe\(network\)[\s\S]*proofIndexWorkPrecisionV2MigrationReadiness[\s\S]*workAmoV8ExactLiveProbe\(network\)/u,
  );
  assert.doesNotMatch(
    sweepSource,
    /pendingValidThrough[\s\S]*Date\.now/u,
  );
  const exactProbeSource = topLevelFunctionSource(
    API_PATH,
    "workAmoV8ExactLiveProbe",
  );
  assert.match(
    exactProbeSource,
    /proofIndexWorkAmoV8WorkerStatusPayload/u,
  );
  assert.doesNotMatch(
    exactProbeSource,
    /proofIndexOperationalStatusPayload/u,
  );
});

check("AMO V8 metadata coalesces identical exact live probes", async () => {
  const singleFlight = isolatedFunction(
    API_PATH,
    "workAmoV8MetadataSingleFlight",
  );
  const inFlight = new Map();
  let loads = 0;
  let release;
  const gate = new Promise((resolve) => {
    release = resolve;
  });
  const load = async () => {
    loads += 1;
    await gate;
    return { ready: true };
  };
  const first = singleFlight(inFlight, "same-exact-probe", load);
  const second = singleFlight(inFlight, "same-exact-probe", load);
  await Promise.resolve();
  assert.equal(loads, 1);
  release();
  assert.deepEqual(
    await Promise.all([first, second]),
    [{ ready: true }, { ready: true }],
  );
  assert.equal(inFlight.size, 0);
  await Promise.all([
    singleFlight(inFlight, "tip-a", async () => {
      loads += 1;
      return "a";
    }),
    singleFlight(inFlight, "tip-b", async () => {
      loads += 1;
      return "b";
    }),
  ]);
  assert.equal(loads, 3);
  await assert.rejects(
    singleFlight(inFlight, "retry", async () => {
      throw new Error("expected metadata readiness failure");
    }),
    /expected metadata readiness failure/u,
  );
  assert.equal(inFlight.has("retry"), false);
  assert.equal(
    await singleFlight(inFlight, "retry", async () => "recovered"),
    "recovered",
  );
  const metadataSource = topLevelFunctionSource(
    API_PATH,
    "workAmoV8Metadata",
  );
  assert.match(
    metadataSource,
    /force !== true[\s\S]*singleFlightBypass !== true[\s\S]*workAmoV8MetadataSingleFlight/u,
  );
  assert.match(
    metadataSource,
    /exactReadinessProbe: immutableProbe[\s\S]*singleFlightBypass: true/u,
  );
});

check("wallet-scoped token stats include pending overlay listings", () => {
  const recomputeStats = isolatedFunction(
    API_PATH,
    "walletScopedTokenPayloadWithComputedStats",
    {
      normalizeTokenScope: (value) =>
        String(value ?? "").trim().toLowerCase(),
    },
  );
  const payload = {
    holders: [{ address: "17W7" }],
    invalidEvents: [{ txid: "invalid" }],
    listings: [
      { confirmed: true, listingId: "confirmed" },
      { confirmed: false, listingId: "pending" },
    ],
    mints: [{ confirmed: true }, { confirmed: false }],
    sales: [{ confirmed: true }, { confirmed: false }],
    stats: {
      activeListings: 0,
      confirmedListings: 0,
      pendingListings: 0,
      tokenScope: "stale",
      walletScoped: true,
    },
    tokens: [{ confirmed: true }, { confirmed: false }],
    transfers: [{ confirmed: true }, { confirmed: false }],
    walletScoped: true,
  };
  const withStats = recomputeStats(payload, "WORK");
  assert.equal(withStats.stats.activeListings, 2);
  assert.equal(withStats.stats.openListings, 2);
  assert.equal(withStats.stats.confirmedListings, 1);
  assert.equal(withStats.stats.confirmedOpenListings, 1);
  assert.equal(withStats.stats.pendingListings, 1);
  assert.equal(withStats.stats.pendingOpenListings, 1);
  assert.equal(withStats.stats.confirmedMints, 1);
  assert.equal(withStats.stats.pendingMints, 1);
  assert.equal(withStats.stats.confirmedSales, 1);
  assert.equal(withStats.stats.pendingSales, 1);
  assert.equal(withStats.stats.confirmedTokens, 1);
  assert.equal(withStats.stats.pendingTokens, 1);
  assert.equal(withStats.stats.confirmedTransfers, 1);
  assert.equal(withStats.stats.pendingTransfers, 1);
  assert.equal(withStats.stats.holders, 1);
  assert.equal(withStats.stats.invalidEvents, 1);
  assert.equal(withStats.stats.tokenScope, "work");
  const unscoped = { listings: [{ confirmed: false }], stats: {} };
  assert.strictEqual(recomputeStats(unscoped), unscoped);
});

