check("AMO V5 migration binds synthetic bond mints to their physical PWM carrier", async () => {
  const queries = [];
  const client = {
    async query(sql, params = []) {
      queries.push({
        params,
        sql: String(sql).trim(),
      });
      return {
        rowCount: queries.length === 2 ? 511 : 0,
        rows: [],
      };
    },
  };
  const result = await backfillCanonicalPositions(client);
  assert.deepEqual(result, {
    events: 511,
    transactions: 0,
  });
  assert.equal(queries.length, 2);
  assert.deepEqual(queries[1].params, [
    WORK_AMO_V5_ACTIVATION_HEIGHT,
    WORK_AMO_V5_POWB_TOKEN_ID,
    WORK_AMO_V5_INCB_TOKEN_ID,
  ]);
  const sql = queries[1].sql;
  for (const required of [
    /canonical_bond_companion AS/u,
    /carrier_event\.protocol = 'pwm1'/u,
    /'canonical-powb-bond-projection'[\s\S]*'infinity-bond'/u,
    /'canonical-incb-bond-projection'[\s\S]*'inception-bond'/u,
    /recipient_output\.vout < carrier\.protocol_vout/u,
    /recipient_output\.address =\s*synthetic_event\.payload->>'minterAddress'/u,
    /NOT COALESCE\(\(\s*synthetic_event\.payload->>'bondRecipientVout' ~[\s\S]*\), false\)/u,
    /preceding_output\.vout <= recipient\.recipient_vout/u,
    /'bondRecipientAmountSats'[\s\S]*'bondRecipientVout'[\s\S]*'protocolVout'[\s\S]*'recordOrdinal'/u,
  ]) {
    assert.match(sql, required);
  }
  assert.doesNotMatch(
    sql,
    /event_row\.protocol = 'pwt1'[\s\S]*protocol_output\.protocol =\s*event_row\.protocol/u,
  );
});

check("AMO V5 independent base vector ignores non-consensus display approximations", () => {
  const actual = Object.fromEntries(
    WORK_AMO_V5_BASE_STATE_FIELDS.map((field) => [field, 1]),
  );
  actual.creditEventFrozenValueQ8 = "2";
  actual.creditMovementFrozenValueQ8 = "1";
  actual.totalUsd = 1.25;
  actual.totalSatsApproximate = Number.MAX_VALUE;
  assert.deepEqual(canonicalWorkAmoIndependentBaseVector(actual), {
    baseState: Object.fromEntries(
      WORK_AMO_V5_BASE_STATE_FIELDS.map((field) => [field, "1"]),
    ),
    creditEventFrozenValueQ8: "2",
    creditMovementFrozenValueQ8: "1",
  });
  assert.throws(
    () =>
      canonicalWorkAmoIndependentBaseVector({
        ...actual,
        browserFlowSats: 1.25,
      }),
    /base field browserFlowSats is unavailable/u,
  );
});

check("AMO V5 apply migration rolls back incomplete replay before any marker or commit", async () => {
  const queries = [];
  const client = {
    async query(sql, params = []) {
      queries.push({
        params,
        sql: String(sql).trim(),
      });
      return { rowCount: 0, rows: [] };
    },
  };
  const audit = {
    authorizationConflicts: 0,
    confirmedParentMetadataGaps: 0,
    duplicatePositions: 0,
    missingFrozenTerms: 0,
    missingPositions: 1,
    postActivationV4Actions: 0,
    postActivationV4Active: 0,
    postV1V3Active: 0,
    syntheticBondPositionGaps: 0,
  };
  const replayEvidence = {
    blockAtomic: false,
    complete: false,
    endTipParity: false,
    reason: "fixture-incomplete-canonical-replay",
  };
  const runMigration = isolatedFunction(
    WORK_AMO_V5_MIGRATION_PATH,
    "runWorkAmoV5Migration",
    {
      WORK_AMO_V5_ACTIVATION_HEIGHT,
      WORK_AMO_V5_DECLARATION_TXID,
      WORK_AMO_V5_FEE_TRANSITION_MODEL,
      WORK_AMO_V5_INVALID_EVENT_MODEL,
      backfillCanonicalPositions: async (migrationClient) => {
        await migrationClient.query(
          "UPDATE proof_indexer.events SET updated_at = updated_at WHERE false",
        );
        return 0;
      },
      canonicalPositionAudit: async () => audit,
      canonicalWorkAmoReplayEvidence: async () => replayEvidence,
      classifyWorkAmoV5LegacyRows: () => ({
        alreadyMigratedEventIds: [],
        eventIds: [],
      }),
      declarationEvidence: () => ({
        declarationTxid: WORK_AMO_V5_DECLARATION_TXID,
        valid: true,
      }),
      legacyRows: async () => ({ rows: [] }),
      pinnedDeclarationRow: async () => ({}),
    },
  );
  await assert.rejects(
    () => runMigration(client, { apply: true }),
    (error) => {
      assert.equal(error?.code, "WORK_AMO_V5_MIGRATION_INCOMPLETE");
      assert.equal(
        error?.details?.replayEvidence?.reason,
        replayEvidence.reason,
      );
      return true;
    },
  );
  const statements = queries.map((query) => query.sql);
  assert.equal(
    statements[0],
    "BEGIN ISOLATION LEVEL SERIALIZABLE",
  );
  assert.ok(
    statements.some((sql) =>
      sql.startsWith("UPDATE proof_indexer.events")
    ),
  );
  assert.equal(statements.at(-1), "ROLLBACK");
  assert.equal(
    statements.filter((sql) => sql === "ROLLBACK").length,
    1,
  );
  assert.equal(
    statements.some((sql) =>
      /INSERT INTO proof_indexer\.meta/u.test(sql)
    ),
    false,
  );
  assert.equal(statements.includes("COMMIT"), false);
});

