  assert.equal(legacySeal.sealBlockHeight, preV5Height);
  assert.equal(legacySeal.sealTransactionBlockHeight, preV5Height);
  assert.equal(legacySeal.sealTxid, sealTxid);
  assert.equal(legacySeal.status, "sealing");
